// 【名詞解釋 terms】{id, sid:科目, zh:中文, en:英文, text:解釋（125 字以上）, refs?:[[科目,章id,節id]], tags?:[分類]}
// 【人物 people】{id, sid, name:中文譯名, en:原名, role:身分, theories:[{t:理論名, n:重點說明, refs?:[[科目,章id,節id]]}]}
