//   欄位暫依「行政法要義」的寫法預設，拿到書後再依其格式調整。
KS.db = {
  terms: [
    {"id":"t-dual-authority","sid":"pol","zh":"雙元權威","en":"Dual Authority","text":"是指一個政治體系中存在兩套獨立且彼此牽制的領導體系，常見於法國第五共和國等半總統制國家。該體系下，總統與總理分別掌握外交與內政權力，但若兩者來自不同政黨，便可能出現「左右共治」情形，導致政策方向分裂。此制度設計旨在避免權力集中、提升政府效率，但也容易因權責不清而產生政治僵局。","tags":["政府體制"]},
    {"id":"t-legal-rational-authority","sid":"pol","zh":"法定／理性的權威","en":"legal/rational authority","text":"韋伯提出的三種正當權威之一，與傳統性權威、魅力型權威並列。其正當性立基於人們信服合理的法律與規則，權力行使來自客觀賦予的權限，因此權力範圍不因人而異，也不能傳給後代。現代官僚組織就是建立在這種權威上：人們服從的是職位與規則，不是掌權者個人。課文也稱法理型權威或合法權威。","refs":[["adm","c2","c2s5"],["pol","c1","c1s5"]]},
    {"id":"t-fundamental-rights","sid":"con","zh":"基本權利","en":"Fundamental Rights","text":"經憲法明文或解釋保障、人民可向國家主張的權利。它與人權是不同概念：人權是人之所以為人而應享有的權利，基本權利則是納入憲法實定秩序者。基本權利主要功能包括防禦權、受益權、制度性保障與國家保護義務等，限制時須符合憲法第 23 條的公益目的、法律保留與比例原則。","refs":[["con","c2","c2s3"],["pol","c5","c5s8"],["con","c1","c1s1"]]},
    {"id":"t-presidential-system","sid":"pol","zh":"總統制","en":"Presidential system","text":"行政大權集中於總統一人的憲政體制，以美國為代表。依薩托利的定義有三點：元首由人民選舉且任期固定；總統是行政首長並領導政府；總統不因國會不信任而去職。行政與立法分立制衡，部會首長只對總統負責。缺點是兩權對立時易生僵局，林茲因此提出「總統制的危險」。我國憲政體制則不屬於此類。","refs":[["pol","c4","c4s2"],["pol","c5","c5s1"],["pol","c5","c5s2"]]},
    {"id":"t-freedom-of-association","sid":"con","zh":"結社自由","en":"Freedom of association","text":"憲法第 14 條保障的權利，包括組成或加入團體、退出團體、團體的存續與活動、內部事務自主，也包含不結社的自由。限制應以法律或明確授權的命令為之。常考案例有釋字 373 號（工會法禁止教育事業技工組工會）、479 號（團體名稱）、644 號（主張共產主義不予許可），均違憲。","refs":[["con","c5","c5s4"],["pol","c8","c8s1"],["con","c3","c3s2"]]},
    {"id":"t-due-process-of-law","sid":"con","zh":"正當法律程序","en":"due process of law","text":"源自英美法，要求國家限制人民權利時不只要有法律依據，程序與內容也必須正當。我國由憲法第 8 條「非依法定程序」導出，釋字 384 號首度引進實質正當法律程序，其後擴及羈押（392 號）、公務員懲戒（396 號）等領域。行政法上的具體內容包括告知、陳述意見、說明理由與救濟。","refs":[["con","c2","c2s2"],["adm","c1","c1s3"],["alaw","c10","c10s1"]]},
    {"id":"t-stakeholders","sid":"adm","zh":"利害關係人","en":"Stakeholders","text":"廣義指與某項政策具相關性的個人或團體，包括制定者、執行者、受益者與受害者，不限於受影響或獲利的一方。它與標的人口不同：標的人口是政策直接實施的對象，例如育兒津貼中符合資格的家庭；間接受影響的人屬於利害關係人，不算標的人口。這是政策分析的常考區別。判斷時要看是否受政策直接實施。","refs":[["adm","c11","c11s1"],["alaw","c7","c7s2"],["alaw","c12","c12s1"]]},
    {"id":"t-legitimacy","sid":"pol","zh":"正當性","en":"Legitimacy","text":"是指人民在心理上感到國家有正當理由行使統治權。若人民是發自內心自願服從國家的法令，而不是因為害怕受到國家強制力的懲罰才被迫服從，則意味著國家的統治具有正當性。德國政治經濟學者韋伯認為統治權威的正當性有三種類型：傳統型權威、領袖魅力型權威、合法理性型權威。","refs":[["pol","c1","c1s5"],["pol","c2","c2s3"],["pol","c4","c4s8"]]},
    {"id":"t-political-socialization","sid":"pol","zh":"政治社會化","en":"Political socialization","text":"是個人接受各種社會期望及文化規範的影響，形成其獨特政治價值觀念及行為型態的過程；若從另一角度界定，一個社會或國家藉各種不同的社會影響力量，培養其社會成員政治價值及行為，以便形成某種政治文化（Political culture）的過程，亦稱為政治社會化。","refs":[["pol","c2","c2s5"],["pol","c7","c7s4"],["pol","c1","c1s3"]]},
    {"id":"t-democratization","sid":"pol","zh":"民主化","en":"Democratization","text":"也稱民主轉型，指政體由威權或極權轉型為民主。杭廷頓在 1991 年《第三波》中指出近代三波民主化浪潮，所謂浪潮是在特定時期內，由非民主轉型為民主的國家數量明顯超過反方向者。第一波起於美國獨立與法國大革命，至 20 世紀 20 年代；第二波在二戰後；第三波始於 1974 年。每一波之後都有回潮。","refs":[["pol","c2","c2s6"],["pol","c4","c4s2"],["pol","c4","c4s5"]]},
    {"id":"t-nationalism","sid":"pol","zh":"民族主義","en":"Nationalism","text":"主張民族應擁有自己的政治單位，也就是「一個民族、一個國家」的民族自決原則。它不同於愛國主義：愛國主義是對祖國的情感與忠誠，例如祖國受攻擊時挺身而出；民族主義者則有其目標與計畫，例如建國、統一或獨立，超出單純的愛國情感。歷史上也有自由民族主義等不同面貌。","refs":[["pol","c2","c2s3"],["pol","c1","c1s7"],["pol","c2","c2s8"]]},
    {"id":"t-judicial-review","sid":"pol","zh":"司法審查","en":"judicial review","text":"法院宣告法律或行政行為違憲、違法而無效或拒絕適用的權力。前提是有一部被各部門視為根本大法的憲法，且司法部門被承認是憲法的合法解釋者。美國的司法審查起源於 1803 年馬伯利控告麥迪遜案，由首席大法官馬歇爾認定國會立法違憲，確立法院的違憲審查權。這也是分散式違憲審查的起點。","refs":[["pol","c5","c5s7"],["adm","c1","c1s5"],["alaw","c2","c2s3"]]},
    {"id":"t-liberalism","sid":"pol","zh":"自由主義","en":"Liberalism","text":"意識形態的一種，中心思想是保障個人自由，並試圖建造一個讓所有個人可以滿足自己利益、實現個人理想的社會。其要項有個人主義、自由、平等、理性、容忍與同意等。古典自由主義主張有限政府與市場；現代自由主義則主張國家適度干預、建立福利國家，強調積極自由。國家角色是兩者最大的差異所在。","refs":[["pol","c2","c2s4"],["pol","c3","c3s1"],["pol","c3","c3s5"]]},
    {"id":"t-semi-presidential-system","sid":"pol","zh":"半總統制","en":"Semi-presidential system","text":"混合議會制與總統制的憲政類型。杜瓦傑的三條件是：總統普選產生；總統有相當實權；另有總理與部長行使行政權，且只要國會不反對即可在職。優點是倒閣與解散機制可化解僵局，總統也有助穩定；缺點是行政權割裂，可能有權無責、有責無權，總統與總理也可能對立。法國第五共和是其典型代表。","refs":[["pol","c5","c5s1"],["pol","c5","c5s3"],["pol","c5","c5s5"]]},
    {"id":"t-proportional-representation","sid":"pol","zh":"比例代表制","en":"Proportional representation","text":"依政黨得票比例分配席次的選舉制度，是選舉制度三大類之一（另為多數代表制與混合制）。它的席次率與得票率較接近，有利小黨與少數代表，常見於共識民主模型，也較容易形成聯合政府。為避免小黨林立，常設政黨門檻，例如我國立委不分區的 5% 門檻（釋字 721 號認為合憲）。","refs":[["pol","c4","c4s5"],["pol","c6","c6s1"],["pol","c6","c6s5"]]},
    {"id":"t-ideology","sid":"pol","zh":"意識形態","en":"ideology","text":"由法國學者特拉西在 18 世紀末創造，原意是「觀念的科學」。呂亞力定義為一套嚴密連結而形成的封閉觀念系統，可作為基本的政治、經濟與社會價值，以及理想政治社會生活方式的基礎。它同時做三件事：描述現在的世界、規劃理想的世界，以及提供實現理想的行動方向。它因此帶有強烈的行動導向。","refs":[["pol","c3","c3s3"],["pol","c4","c4s7"],["pol","c6","c6s6"]]},
    {"id":"t-constitutional-system","sid":"pol","zh":"憲政體制","en":"Constitutional system","text":"指立法、行政及司法三權之間如何安排，並依行政權歸屬及行政與立法關係為指標，可分為總統制（Presidential government）、內閣制（Cabinet government）與半總統制（Semi-presidentialism）。判斷時要看行政權由誰掌握、內閣向誰負責，以及有無倒閣與解散國會的機制。","refs":[["pol","c1","c1s8"],["pol","c4","c4s2"],["pol","c3","c3s4"]]},
    {"id":"t-electoral-system","sid":"pol","zh":"選舉制度","en":"Electoral system","text":"把選票轉換為席次的一套規則，大致分為多數代表制、比例代表制與混合制三類。選舉的功能有五：提供政權正當性；形成民意與政策偏好；作為衝突的制度性解決管道；讓民眾取得政治資訊、學習民主；串連政黨與利益團體等政治部門。制度不同，對政黨體系的影響也不同。法國總統選舉採兩輪投票制。","refs":[["pol","c6","c6s1"],["pol","c6","c6s2"],["pol","c4","c4s2"]]},
    {"id":"t-across-boundary-governance","sid":"adm","zh":"跨域治理","en":"across-boundary governance","text":"指兩個或兩個以上的轄區、部門或組織，因業務、功能或疆界相接，形成問題相互依賴、責任相互重疊時，透過協力、社區參與、公私合夥或契約等方式，以整體視野共同解決問題。林水波、李長晏等人整理為跨越轄區、跨越部門、跨越公私界線的合作。空汙、河川都是典型議題。它強調協力，不是由單一機關處理。","refs":[["adm","c12","c12s2"],["adm","c12","c12s1"],["adm","c13","c13s3"]]},
    {"id":"t-constitutionalism","sid":"pol","zh":"憲政主義","en":"constitutionalism","text":"主張政府權力必須受憲法限制的思想，要求政府依憲法行事、分權制衡並保障人權。民主回答「誰來統治」，憲政主義回答「權力如何受限」，兩者可能衝突，因為多數決可能侵害少數權利。結合兩者的是憲政民主或自由民主；只有選舉而不受憲法限制的，則是非自由主義式民主。其核心是有限政府與保障人權。","refs":[["pol","c4","c4s1"],["pol","c5","c5s8"]]},
    {"id":"t-socialism","sid":"pol","zh":"社會主義","en":"Socialism","text":"對工業資本主義的反動，主張以共同所有權取代私有財產，由社會的公共力量管理經濟活動，將生活與享受公平分配，以謀求社會全體幸福。要點有社群、合作、平等、階級政治與共有制。後來分成兩大路線：主張革命的共產主義，以及主張議會改革的社會民主主義。其核心是追求社會與經濟平等。","refs":[["pol","c3","c3s2"],["pol","c3","c3s6"],["con","c1","c1s1"]]},
    {"id":"t-formal-organization","sid":"adm","zh":"正式組織","en":"formal organization","text":"兩個或兩個以上的人有意識協調行動或勢力的體系，具固定結構與層級節制。巴納德強調組織成立須有共同目標、協力意願與溝通。正式組織常伴隨非正式組織，後者可能給予組織活力，也可能加以限制，甚至在工作目標和方法上產生歧見，所以兩者要合併觀察。韋伯的官僚型模也屬於對正式組織的分析。","refs":[["adm","c3","c3s2"],["adm","c6","c6s3"],["adm","c7","c7s3"]]},
    {"id":"t-feminism","sid":"pol","zh":"女性主義","en":"Feminism","text":"主張性別平等、批判父權結構的思想。在國家理論上，女性主義批評父權國家，認為國家透過區分公私領域，把女性禁錮在私人分工中，排除於政治經濟之外，因此主張國家應積極提升女性的教育與政治地位。注意「父權國家」是女性主義的批判用語，與保守主義的有機體與家長主義不同。","refs":[["pol","c2","c2s4"],["pol","c2","c2s1"],["pol","c3","c3s6"]]},
    {"id":"t-minorities-within","sid":"pol","zh":"少數中的少數","en":"Minorities within Minorities","text":"多元文化主義的內部難題：國家賦予族群集體權利、尊重其傳統與自治時，族群內部較弱勢的成員（常舉女性，也包括異議者、同性戀者）可能因此更難對抗傳統規範。歐肯在〈多元文化主義對女性有害嗎？〉（1999）提出這項批評，常舉的實例是印度 Shah Bano 案與美國 Santa Clara Pueblo v. Martinez。金里卡區分外部保護與內部限制，支持前者、反對後者。支持者另回應：文化不是鐵板一塊，改革可由族群內部推動。","refs":[["pol","c3","c3s6"],["con","c3","c3s2"]]},
    {"id":"t-public-goods","sid":"adm","zh":"公共財","en":"Public Goods","text":"具有非排他性與非敵對性的財貨：無法排除他人使用，一人使用也不減少他人享用，例如國防。因為成果由所有人共享，理性自利的個人會想搭便車，若不由政府提供就會供給不足，這是政府介入市場的重要理由。規費的對象則是可以排他的特定服務，所以才能收費。「非排他、非敵對」是常考的兩個特性。","refs":[["adm","c1","c1s2"],["pol","c6","c6s4"],["adm","c1","c1s1"]]},
    {"id":"t-span-of-control","sid":"adm","zh":"控制幅度","en":"span of control","text":"一位主管能有效直接指揮監督的部屬人數，超過限度，主管管不好，部屬也會不滿。最早提出這個觀念的是葛蘭鳩納斯，他指出部屬人數呈算術級數增加時，上級與部屬之間的關係呈幾何級數增加。它與組織層級相關：控制幅度小則層級多，控制幅度大則組織較扁平。適切的幅度要視工作性質與主管能力而定。","refs":[["adm","c7","c7s2"],["adm","c4","c4s3"],["adm","c7","c7s1"]]},
    {"id":"t-unitary-state","sid":"pol","zh":"單一國","en":"unitary state","text":"國家結構的一種，主權集中於中央，地方政府權力由中央授予，中央可調整甚至取消地方權限，例如英國、法國、日本與我國。相對的是聯邦國，中央與各邦的權限都受憲法保障，任何一方不能單方面改變，例如美國、德國、瑞士。另有邦聯，是主權國家間較鬆散的結合。判斷標準在於地方權限的來源。","refs":[["pol","c5","c5s4"],["con","c13","c13s1"],["jur","c1","c1s5"]]},
    {"id":"t-parliamentary-system","sid":"pol","zh":"議會內閣制","en":"Parliamentary system","text":"以英國為代表的憲政體制。元首虛位，首相掌握實權；人民選出國會，由多數黨組閣，只有一元民主正當性。行政對立法負責，內閣失去國會信任就會被倒閣，國會也可能被解散。內閣若沒有過半支持，可能出現聯合內閣或少數政府；德國則以建設性不信任投票增加穩定。其特徵是行政與立法融合，而非分立。","refs":[["con","c9","c9s2"],["pol","c5","c5s1"],["con","c1","c1s5"]]},
    {"id":"t-administrative-man","sid":"adm","zh":"行政人","en":"administrative man","text":"賽蒙提出的決策者假設，用來取代古典經濟學的「經濟人」。經濟人被假設為完全理性、自利並追求效用極大化；賽蒙則發現決策受資訊、時間、計算能力與慣例等限制，只能做到有限理性，所以行政人追求的是滿意解而非最佳解，這就是滿意決策。此概念是決策理論的核心。它與經濟人的對照是常考重點。","refs":[["adm","c3","c3s3"],["adm","c4","c4s4"],["adm","c8","c8s4"]]},
    {"id":"t-civil-disobedience","sid":"pol","zh":"公民不服從","en":"civil disobedience","text":"人民基於良知或對正義的信念，公開、非暴力地違反特定法律或政策，以表達抗議並尋求改變，通常也願意承擔法律後果。在政治學上，它常與正當性一起討論：李普賽指出，正當性一旦式微，人民就會開始不守法、不繳稅，最後引發公民不服從。定義部分課文未詳述，請對照書本。","refs":[["pol","c1","c1s5"],["pol","c8","c8s1"],["pol","c6","c6s7"]]},
    {"id":"t-representative-democracy","sid":"pol","zh":"代議民主","en":"Representative democracy","text":"人民選出代表，委託其代為討論與決議，並將權力授予政府的民主形式。關於代表與人民的關係有兩說：代理說要求民意代表完全依人民意志行事，不許有自己的想法；委任說認為人民選出代表即是託付授權，代表有自主性可獨立思考。巴伯批評代議民主是「弱勢民主」。代理說與委任說的區別是常考重點。","refs":[["pol","c4","c4s3"],["adm","c10","c10s7"],["pol","c3","c3s2"]]},
    {"id":"t-informal-organization","sid":"adm","zh":"非正式組織","en":"informal organization","text":"又稱小團體。組織成員常因生活背景、興趣嗜好等相近而形成小團體，並有自己的一套行為規範作為成員準繩，影響和約束力有時甚至超越正式組織；兩者衝突時，正式組織往往只能默許或修改規定以順應情勢。霍桑實驗發現它對生產力的影響，韋伯的官僚型模則被批評忽略了它。這是修正時期的重要發現。","refs":[["adm","c2","c2s5"],["adm","c3","c3s1"],["adm","c3","c3s2"]]},
    {"id":"t-vote-of-no-confidence","sid":"pol","zh":"不信任投票","en":"Vote of no confidence","text":"國會追究內閣責任、迫使其下台的手段，也是解決行政與立法僵局的方法，通過後可要求相關官員去職甚至全體內閣總辭，是內閣制國會至上的保證。各國常設限制，如提案門檻、冷卻期、絕對多數。德國建設性不信任投票要求須先選出繼任者，以避免倒閣後政府真空。我國立法院對行政院院長也有不信任案。","refs":[["pol","c5","c5s1"],["pol","c6","c6s6"],["con","c9","c9s2"]]},
    {"id":"t-divided-government","sid":"pol","zh":"分立政府","en":"Divided government","text":"由不同政黨掌握不同政府機關的狀態，典型是總統所屬政黨在國會未過半。其形成的關鍵是行政與立法分別由人民選出、分權制衡。分立政府容易因行政立法對峙造成僵局、政策停滯與立法效能不彰。相對的是一致政府。多黨制下還要看是否存在多數聯盟，以及總統黨是否在聯盟內。","refs":[["pol","c5","c5s2"],["pol","c5","c5s9"]]},
    {"id":"t-separation-of-powers","sid":"pol","zh":"三權分立","en":"Separation of powers","text":"由孟德斯鳩在《論法的精神》提出，主張將國家權力分為立法、行政、司法三個獨立部門，目的在於權力制衡（Checks and Balances），防止權力過度集中於單一機關，以避免專制並保障人民自由。除水平分權外，還有中央與地方的垂直分權；我國憲法採五權架構。","refs":[["pol","c2","c2s7"],["pol","c5","c5s2"],["adm","c1","c1s1"]]},
    {"id":"t-capitalism","sid":"pol","zh":"資本主義","en":"Capitalism","text":"是種以私有財產鞏固為核心的學說，並不希望其他任何勢力介入，而讓市場力量控制財產的流通、估值與占有。認為商品具有固有「市場價值」，此是由市場的供給與需求決定，而政府不該無端介入，應讓私人享有生產的利潤，使社會整體利益遞增。早期的企業資本主義認為自由市場是絕對正確的，晚近的社會資本主義則試圖平衡資本主義與社會主義間的差異，並且以適當的經濟與政治管制來取得穩定發展。","refs":[["pol","c1","c1s8"],["pol","c1","c1s5"],["pol","c1","c1s7"]]},
    {"id":"t-systems-theory","sid":"adm","zh":"系統理論","en":"systems theory","text":"整合時期的組織理論，把組織看成由相互依賴的部分組成、與外在環境持續互動的整體，具備投入、轉換、產出與回饋。帕森斯強調系統不只指各部分相互依賴，也指整體與環境相互依存。開放系統要與環境交換資源才能生存。「組織須與環境互動」是這一派的觀點，不是霍桑實驗的發現。","refs":[["adm","c3","c3s1"],["adm","c4","c4s1"],["adm","c2","c2s1"]]},
    {"id":"t-political-communication","sid":"pol","zh":"政治溝通","en":"Political communication","text":"個人或團體透過表達管道，把政治性訊息傳達給他人，希望影響對方對政治事務看法的過程。要素包括溝通者、訊息、媒介、接收者（受眾）與回應。回應又分啟發、改變、強化與付諸行動四種方式。媒介當中以大眾媒介擴散效果與影響力最大；接收者的知識與利益也會影響效果。這些要素是答題時的基本架構。","refs":[["pol","c2","c2s5"],["pol","c7","c7s3"]]},
    {"id":"t-authoritarianism","sid":"pol","zh":"威權主義","en":"Authoritarianism","text":"林茲定義威權政體為：有限的、不負責任的政治多元；沒有精密的指導思想；除特定時期外沒有廣泛深入的政治動員；領袖在界定不清但可預測的範圍內行使權力。杭廷頓分為一黨制、軍事政權與個人獨裁三類。它與極權主義的差別在於控制範圍，威權不追求全面控制社會。威權體制不一定要求人民積極效忠。","refs":[["pol","c3","c3s6"]]},
    {"id":"t-conservatism","sid":"pol","zh":"保守主義","en":"Conservatism","text":"意識形態的一種，認為傳統是良善的，應予保存與保護，代表人物是英國的柏克，提出「變革是為了保存」。其要項有：傳統與實用主義，認為人類理性有限；人的不完美性，需要秩序約束；有機論與階級性，把社會視為有機體；以及對權威的服從。國家觀是有機體與家長主義。它並不反對一切改變，而是主張漸進。","refs":[["pol","c1","c1s8"],["pol","c2","c2s4"],["pol","c3","c3s4"]]},
    {"id":"t-populism","sid":"pol","zh":"民粹主義","en":"Populism","text":"指具有個人魅力的領袖人物，動輒以人民福祉為號召，取得廣泛民眾支持後，做出超越憲政規範的事情。它訴諸人民與菁英的對立，常繞過代議機構直接訴諸群眾。政治學上把它視為直接民主與選舉的隱憂之一，因為選舉與公投未必經過深入討論，容易被情緒動員。它因此可能對憲政秩序造成威脅。","refs":[["pol","c4","c4s6"],["pol","c9","c9s3"],["pol","c3","c3s3"]]},
    {"id":"t-plebiscite","sid":"pol","zh":"公民複決","en":"Plebiscite","text":"由公民直接投票決定特定事項的直接民主機制，常用於憲法修改或重大決策。依憲法修改的難易，剛性憲法的修改比一般法律困難，須經特別多數或公民複決。我國憲法增修條文也規定，修憲案與領土變更案須經公告後，由全國選舉人投票複決。它與人民創制不同，複決是對既有提案表決。","refs":[["pol","c5","c5s8"],["pol","c5","c5s3"],["con","c1","c1s2"]]},
    {"id":"t-policy-legitimation","sid":"adm","zh":"政策合法化","en":"policy legitimation","text":"政府機關把規劃好的方案，依法定程序送請有權核准的機關或人員審議通過，使其取得合法地位的過程。它不只發生在國會，行政機關內部也有合法化程序，例如部會方案經行政院會議通過、行政命令經首長核定發布；涉及法律或預算的方案，才再送立法院審議。考題常以「只能在議會」為錯。","refs":[["adm","c11","c11s2"],["adm","c11","c11s1"]]},
    {"id":"t-benchmarking","sid":"adm","zh":"標竿學習","en":"benchmarking","text":"找出表現最佳的組織或作法作為標竿，比較自己與標竿的差距，學習其流程並加以改善。美國全錄公司 1979 年起有系統地推動，之後引進公部門，成為策略規劃與管理工具。重點在學習對方「怎麼做」，屬於過程導向的改善工具，而不只是比較結果；標竿對象也可以是組織內部單位。","refs":[["adm","c14","c14s6"]]},
    {"id":"t-nation-state","sid":"pol","zh":"民族國家","en":"Nation-state","text":"民族與國家兩個概念的結合，是近代主要的國家形式。民族國家初期為打破封建割據而形成專制君主，工業革命後再走向自由民主與代議政治。筆記歸納三要件：與國家歷史息息相關或有夠久的建國史；擁有悠久的菁英文化傳統與獨特語言文學；有休戚與共的民族情操。例如日本、泰國。","refs":[["pol","c2","c2s1"],["pol","c2","c2s3"],["pol","c6","c6s3"]]},
    {"id":"t-hawthorne-experiment","sid":"adm","zh":"霍桑實驗","en":"Hawthorne experiment","text":"在美國西方電氣公司霍桑工廠進行的一系列研究，由哈佛大學的梅堯、羅斯力斯柏格與懷海德等人接續，包括繼電器裝配等實驗。結果發現員工不只受經濟誘因驅動，工作場所的社會情境與非正式組織都會影響生產力，因而開啟人群關係學派，也使行政學由傳統時期走入修正時期。這是修正時期的開端。","refs":[["adm","c3","c3s1"],["adm","c2","c2s2"],["adm","c7","c7s3"]]},
    {"id":"t-failed-state","sid":"pol","zh":"失敗國家","en":"failed state","text":"未能滿足和履行主權政府應有基本條件與責任的國家，通常反映社會、政治與經濟上的全面失敗，常伴隨普遍貪污、犯罪，以及難民等非自願人口遷移。特徵包括失去對領土的控制等。福山認為要維持政治穩定，須依序建立有效國家、法治與民主問責，缺乏這些就是失敗國家。阿富汗、葉門、南蘇丹常被列入。","refs":[["pol","c2","c2s8"]]},
    {"id":"t-privatization","sid":"adm","zh":"民營化","en":"privatization","text":"把原由政府提供的服務或經營的事業，移轉由民間辦理或擁有，包括出售國營企業、業務委外等。最早大規模推動的是英國柴契爾政府。它是新公共管理與政府再造的重要手段，我國組織改造的「委外化」也屬相近作法。政治學也把它視為國家權力向外移轉、走向國家黃昏的方向之一。","refs":[["adm","c1","c1s5"],["adm","c6","c6s2"],["pol","c2","c2s7"]]},
    {"id":"t-management-by-objectives","sid":"adm","zh":"目標管理","en":"management by objectives, MBO","text":"由杜拉克 1954 年在《管理實務》提出：管理者和部屬透過一定過程共同設定目標，以目標要達成的結果界定彼此的職責範圍，並作為各單位運作的指導與考核依據。它強調參與、自我控制與成果考核。近年企業與政府也使用 OKR（目標與關鍵成果）這類相近的目標管理工具。","refs":[["adm","c14","c14s1"],["adm","c3","c3s5"]]},
    {"id":"t-coalition-government","sid":"pol","zh":"聯合政府","en":"Coalition government","text":"是由兩個以上的政黨結盟組成，儘管需要共享執政權力，但同時也能掌握議會半數以上席次，藉此確保政府政策能夠得到議會支持，也因此又稱作「多黨政府」（multiparty government）。實際上，聯合政府在全球民主國家中已經是十分常見的治理模式，特別是選舉制度採用比例代表制的國家，更經常能觀察到聯合政府出現。","refs":[["pol","c4","c4s5"],["pol","c6","c6s6"],["pol","c6","c6s1"]]},
    {"id":"t-pressure-groups","sid":"pol","zh":"壓力團體","en":"Pressure groups","text":"即利益團體，指為維護或促進共同利益，從事政治活動以影響政府決策的團體，但不直接競逐政權。杜魯門認為它基於共同態度形成行為模式，並向其他團體提出要求。依目的可分為保護性團體（如工會、商業組織）與促進性團體（如環保、反菸團體）。它與政黨的差別在於不提名候選人執政。","refs":[["pol","c6","c6s4"],["pol","c1","c1s3"]]},
    {"id":"t-iron-triangle","sid":"pol","zh":"鐵三角","en":"Iron triangle","text":"利益團體會在部分議題上，同時鎖定國會相關委員會與行政部門之官僚，以設法滿足彼此之間的利益，而此三者的關係便是「鐵三角」，次級體系、次級政府與愜意小三角都是描述這樣的關係。舉美國為例，軍事產業和政府（國防部與軍隊）組成軍產複合體，並與國會中相關委員會爭取合作、分配美國預算大餅。","refs":[["pol","c5","c5s10"],["pol","c6","c6s4"],["adm","c11","c11s2"]]},
    {"id":"t-totalitarianism","sid":"pol","zh":"極權主義","en":"Totalitarianism","text":"利用現代技術形成的新統治形態，以意識形態建立對社會的全面性控制。鄂蘭在《極權主義的起源》分析其形成脈絡。弗里德里希與布里辛斯基歸納六項特徵，包括無所不包的官方意識形態、單一群眾政黨、秘密警察的恐怖統治等。它與威權主義的差別在控制範圍與動員程度。極權要求對人民生活全面滲透。","refs":[["pol","c4","c4s7"]]},
    {"id":"t-decision-theory","sid":"adm","zh":"決策理論","en":"decision theory","text":"研究組織如何作成決定的理論，以賽蒙為代表。他認為傳統行政學只注意執行而忽略決定，因而提出「行政人」與有限理性，並主張區分價值與事實判斷。決策者受資訊、時間與能力限制，追求滿意解而非最佳解。另在政策評估上，「決策理論評估」指納入多元利害關係人目標的評估方式。","refs":[["adm","c11","c11s4"],["adm","c3","c3s1"],["adm","c3","c3s3"]]},
    {"id":"t-parkinson-s-law","sid":"adm","zh":"白京生定律","en":"Parkinson's law","text":"由白京生提出的組織病象定律，又稱用人麻痺症，描述政府與企業組織都可能出現的無效率現象：機關人員會持續增加，與實際工作量未必相關，首長傾向增加部屬而非競爭者，工作也會膨脹到填滿可用時間。它與彼得原理、邁爾斯定律、莫非定律、寡頭鐵律同屬常考定律。它描述的是組織膨脹的病象。","refs":[["adm","c7","c7s8"],["adm","c5","c5s1"]]},
    {"id":"t-transformational-leadership","sid":"adm","zh":"轉換型領導","en":"transformational leadership","text":"柏恩斯（J. M. Burns）1978 年在《領導》一書提出，與交易型領導相對。領導者不只以報酬交換服從，而是提升部屬的動機與價值層次，激發部屬超越個人利益，追求組織目標。貝斯（B. M. Bass）進一步研究，歸納其要素，包括魅力、激勵、智識啟發與個別關懷等。","refs":[["adm","c8","c8s6"],["adm","c8","c8s1"]]},
    {"id":"t-individualism","sid":"pol","zh":"個人主義","en":"Individualism","text":"個人主義是自由主義意識形態的基本假設，它反映對人類個體的尊重，也同時排除任何集體主義的思考。自由主義認為既然所有團體都是由個人組成，這意味他們享有相同的價值。個人主義的思考對於以自由主義為基礎的學科影響深遠，例如經濟學中的「個人理性選擇」的基本假定。","refs":[["pol","c3","c3s1"],["pol","c3","c3s2"],["pol","c3","c3s5"]]},
    {"id":"t-welfare-state","sid":"pol","zh":"福利國家","en":"Welfare state","text":"國家經由強制性、集體性與非差別性的系統提供法定福利服務，透過社會立法明定對公民福祉的責任，要保障最低的全面要求。現代自由主義主張國家適度干預市場、建立福利國家，關注弱勢，並強調積極自由；美國小羅斯福的新政屬此路線。福利擴張也是行政國形成的背景之一。這也是政府職能擴張的表現。","refs":[["pol","c3","c3s1"],["pol","c3","c3s2"],["pol","c1","c1s8"]]},
    {"id":"t-pork-barrel","sid":"pol","zh":"肉桶立法","en":"Pork barrel","text":"議員為討好選區選民、爭取連任，藉法律案或預算審議挾帶對自己選區有利的條款或補助，對整體未必必要，就像大家瓜分一桶豬肉，是合法化形式下的政治分贓，也是一種競租。要與滾木立法區別：滾木立法是議員之間互相支持對方的法案，彼此交換選票。兩者都常見於考題，容易互相混淆。","refs":[["pol","c5","c5s11"],["pol","c6","c6s5"],["adm","c11","c11s2"]]},
    {"id":"t-value-neutrality","sid":"adm","zh":"價值中立","en":"value-neutrality","text":"研究者應區分事實與價值，不把個人價值判斷帶入研究的主張。韋伯把它用於社會科學，行為主義也強調此點，傳統行政學更有「行政中立」的影子。後行為主義則批評科學實際上無法做到價值中立，應重視價值判斷；新公共行政也拒絕行政中立的觀點，轉而重視社會公平。這是兩派爭論的核心問題所在。","refs":[["adm","c3","c3s1"],["pol","c1","c1s4"],["adm","c1","c1s3"]]},
    {"id":"t-ngo","sid":"pol","zh":"非政府組織","en":"NGO (non-governmental organization)","text":"獨立於政府之外、非營利的民間組織，常就人權、環境、貧窮等議題進行倡議與服務，例如國際特赦組織、綠色和平組織。全球公民社會透過國際 NGO 與跨國網絡連結，被認為是全球治理的重要基礎，能補充國家與國際組織的不足。國內討論時常與非營利組織（NPO）交互使用。","refs":[["pol","c6","c6s7"],["pol","c9","c9s2"],["adm","c6","c6s3"]]},
    {"id":"t-civil-law","sid":"pol","zh":"大陸法系","en":"civil law","text":"以成文法典為主要法源的法律體系，法官依法條適用法律，例如德國、法國、日本與我國。相對的是普通法（英美法系），依遵循先例原則運作，法官在個案中發展法律。在法院體制上，大陸法系常有公私法二元的法院，並發展出集中式違憲審查；普通法系多採分散式審查。這是兩大法系最基本的區別。","refs":[["pol","c5","c5s7"],["jur","c1","c1s2"],["alaw","c1","c1s2"]]},
    {"id":"t-job-enrichment","sid":"adm","zh":"工作豐富化","en":"job enrichment","text":"工作設計的一種，屬垂直擴展：除了增加工作項目，還賦予更具挑戰性的內容與自主性，讓員工承擔更多規劃與控制的責任，獲得成長機會。赫茲伯格的兩因理論是其理論基礎。它與工作擴大化不同，後者是水平增加工作種類；工作輪調則是讓人員在不同工作間輪換。一個是垂直擴展，一個是水平擴展。","refs":[["adm","c3","c3s5"],["adm","c7","c7s5"],["adm","c3","c3s4"]]},
    {"id":"t-blacksburg-manifesto","sid":"adm","zh":"黑堡宣言","en":"Blacksburg Manifesto","text":"1983 年由美國維吉尼亞理工大學的學者（萬斯萊等人）提出，被視為制度化的明諾布魯克觀點。它重新檢視公共行政在民主憲政中的地位與角色，主張公共行政不應只指政府或官僚，應從憲法確立其正當性，文官是憲政秩序的維護者，並回應當時對官僚的批評。它也是對新公共行政觀點的延續。","refs":[["adm","c5","c5s1"],["adm","c5","c5s2"],["adm","c1","c1s4"]]},
    {"id":"t-entrepreneurial-government","sid":"adm","zh":"企業型政府","en":"entrepreneurial government","text":"歐斯本與蓋伯勒在《新政府運動》提出，主張為政府注入企業精神，屬於新公共管理的一支。例如導航式政府「掌舵而非划槳」、社區性政府授能社區、競爭性政府引進競爭，並以顧客與成果為導向。它要求政府重視產出與績效，而不是把政府當成企業，也不等於民營化。政府與企業的本質差異仍然存在。","refs":[["adm","c6","c6s1"],["adm","c6","c6s5"],["adm","c5","c5s1"]]},
    {"id":"t-organizational-pathology","sid":"adm","zh":"組織病象","en":"organizational pathology","text":"組織在成長與運作過程中出現的反功能現象，使組織偏離原本目標與效率。墨頓提出反功能觀念，指出過度依賴法規會造成目標錯置。張潤書把成因分為規模龐大、法規森嚴等五類。常考的定律有白京生定律、寡頭鐵律、彼得原理、邁爾斯定律與莫非定律。這些定律描述的現象要分清楚，不要混淆。","refs":[["adm","c7","c7s8"],["adm","c7","c7s5"]]},
    {"id":"t-organization-development","sid":"adm","zh":"組織發展","en":"organization development, OD","text":"以行為科學方法，有計畫地推動組織整體變革，提升組織效能與適應能力，促進公開互信並以民主方式解決問題。李文是其先驅，他的力場分析與解凍、變革、再結凍三階段是基本架構。民主行政也主張在官僚組織內推動組織發展。它與學習型組織常一起討論。它重視成員參與和長期的改善過程。","refs":[["adm","c5","c5s4"],["adm","c7","c7s5"],["adm","c1","c1s3"]]},
    {"id":"t-transactional-leadership","sid":"adm","zh":"交易型領導","en":"transactional leadership","text":"把領導看成領導者與部屬之間的交換：部屬提供努力與順從，領導者提供報酬與升遷。理論根源是巴納德的貢獻與滿足平衡論，只要部屬相信貢獻與報酬公平，就願意服從。貝斯歸納其要素包括條件式獎賞與例外管理。與之相對的是轉換型領導，後者著重提升部屬的動機與價值。這兩者是新型領導的基本對照。","refs":[["adm","c8","c8s6"]]},
    {"id":"t-tax-expenditure","sid":"adm","zh":"稅式支出","en":"tax expenditure","text":"政府以減免稅捐等租稅優惠達成政策目的，實質上等於放棄應收的稅收，與編列預算補助有類似效果，但不經一般支出的審議，透明度較低。常見形式有免稅額、扣除額、減免與緩課。要注意與規費區別：規費依受益者付費，是向特定服務使用者收取的費用。定義細節請對照課文。實質上是政府的一種隱藏支出。","refs":[["adm","c10","c10s3"]]},
    {"id":"t-target-population","sid":"adm","zh":"標的人口","en":"target population","text":"政策直接實施的對象，例如育兒津貼的標的人口是符合資格的家庭。它不包括間接受影響者，那些人屬於利害關係人。在政策執行與評估上，標的人口的順服程度會影響政策成敗，所以規劃時要考量其人數、行為與配合意願。考題常把標的人口與利害關係人混用，要特別留意。這是政策分析的基本概念。","refs":[["adm","c11","c11s1"],["adm","c11","c11s3"],["adm","c11","c11s4"]]},
    {"id":"t-open-data","sid":"adm","zh":"開放資料","en":"open data","text":"政府把持有的資料以機器可讀、可自由取用的格式公開，供民間再利用。它是開放政府的重要工具，配合透明、參與與協力等原則，也和資訊公開相關但不同：資訊公開著重讓人民查得到資訊，開放資料進一步讓資料可以再加值。我國自 2019 年起推動開放政府國家行動方案。","refs":[["adm","c14","c14s7"]]},
    {"id":"t-pluralism","sid":"pol","zh":"多元主義","en":"Pluralism","text":"認為影響政策的力量是分散的，並非集中在特定權力者身上，不同領域的行動者透過競爭、選舉或遊說影響政府決策，國家是團體之間協調的中立仲裁者。古典代表是道爾的《誰在統治？》。缺點是忽略國家本身的制度結構與影響力，也難避免資源多的團體聲音較大。代表學者應以道爾為準，不是伊斯頓。","refs":[["pol","c1","c1s8"],["pol","c2","c2s4"],["pol","c6","c6s4"]]},
    {"id":"t-iron-law-of-oligarchy","sid":"pol","zh":"寡頭鐵律","en":"Iron law of oligarchy","text":"米歇爾斯觀察各種社會主義政黨的活動，發現無論這些政黨在開始的時候如何標榜民主與大眾化，但到頭來一定被少數領袖份子所操控，此即為「寡頭鐵律」。他認為：「機關組織規模越大，領導階層的權力就越大，部屬的權力就越小，權力最後都集中於少數人手中。」課文譯為米契爾斯，指同一人。","refs":[["pol","c2","c2s4"],["pol","c4","c4s3"],["pol","c6","c6s3"]]},
    {"id":"t-probability-sampling","sid":"pol","zh":"隨機抽樣","en":"Probability sampling","text":"又稱機率抽樣，每個樣本被抽中的機會是一樣的，相較於志願回應的樣本時常存在偏差，隨機樣本最大的優點是具有公正不偏性。一般而言，嚴謹的隨機抽樣可以產生具有代表性的樣本，使得意見調查的分析結果能進一步推論到母體的整體情況。它是民意調查與審議式民調的基礎方法。","refs":[["pol","c4","c4s4"],["adm","c13","c13s3"],["adm","c14","c14s5"]]},
    {"id":"t-premier-presidentialism","sid":"pol","zh":"總理總統制","en":"Premier-presidentialism","text":"舒加特與凱瑞提出的半總統制次類型。總統任命閣揆，但任命後閣揆只對國會負責，總統不能自行免職閣揆，例如法國。總統與國會多數黨不一致時，通常走向共治，不會出現分立政府。相對的是總統議會制，閣揆同時對總統與國會負責，總統權力較大，例如我國、俄羅斯。這是兩種次類型的主要區別。","refs":[["pol","c5","c5s3"],["pol","c5","c5s5"]]},
    {"id":"t-publicness","sid":"adm","zh":"公共性","en":"Publicness","text":"公共行政有別於企業管理的核心特質，也是定義行政的傳統觀點之一（另有政治、管理、公共政策觀點）。它指行政涉及公共利益與公權力，要受民意、法律與公共監督，並須回應社會多元價值。討論公共性時常連結公共利益的判斷準則，例如全鍾燮提出的八項標準。這是公私部門差異的基礎概念。","refs":[["adm","c1","c1s3"],["adm","c1","c1s4"],["adm","c5","c5s3"]]},
    {"id":"t-free-rider","sid":"adm","zh":"搭便車","en":"Free Rider","text":"不付出成本卻享受他人努力成果的行為。奧爾森在《集體行動的邏輯》中指出，團體爭取的若是公共財，理性自利的個人就會想「反正別人會出力」，導致團體難以動員，這是集體行動困境。團體越大越難動員，解決方法是提供只給參與者的選擇性誘因。公共財因此常須由政府提供。","refs":[["adm","c1","c1s1"],["adm","c1","c1s2"],["pol","c2","c2s9"]]},
    {"id":"t-ideal-type","sid":"adm","zh":"理想型","en":"Ideal type","text":"韋伯提出的分析工具，也譯理念型，是從現實中抽取出來、作為分析比較基準的純粹概念模型，不是說現實中真有這樣完美的存在，也不是價值上的「理想」。他的官僚制度就是一種理想型，建立在合法權威的觀念上，特徵有依法行政、層級節制、對事不對人、專業分工等。它是分析工具，不是現實描述。","refs":[["adm","c2","c2s5"],["adm","c8","c8s2"],["adm","c7","c7s8"]]},
    {"id":"t-motivation-hygiene-theory","sid":"adm","zh":"激勵保健理論","en":"motivation-hygiene theory","text":"赫茲伯格 1950 年代後期提出，又稱兩因理論。能防止不滿的是保健因素，又稱維持因素，包括組織政策與管理、上司監督、報酬、人際關係、工作環境，只能消除不滿；能帶來滿足的是激勵因素，如成就、賞識、工作本身、責任與成長。它是工作豐富化的理論基礎。兩類因素要分清楚，是常考重點。","refs":[["adm","c3","c3s4"],["adm","c7","c7s5"]]},
    {"id":"t-deliberative-democracy","sid":"pol","zh":"審議式民主","en":"deliberative democracy","text":"主張公共政策應由受影響的公民或其代表，經理性、反思的公共討論後形成，不只是投票加總偏好。常以哈伯瑪斯的溝通理性為基礎。要件是資訊充分、參與者具代表性、平等對話、以公共利益為核心。形式包括審議式民調、公民陪審團與願景工作坊，限制則有審議偏見與排他性。它重視討論的品質。","refs":[["pol","c4","c4s4"],["adm","c10","c10s7"],["pol","c4","c4s5"]]},
    {"id":"t-majoritarian-democracy","sid":"pol","zh":"多數民主","en":"majoritarian democracy","text":"李帕特提出的民主模型，又稱西敏寺模型，以英國為代表。邏輯是意見不一致時由多數決定，權力集中、責任清楚，呈現排他、競爭與對立的特性。特徵包括一黨過半內閣、內閣優勢、非對稱兩院制等。它適合同質性高的社會；相對的共識民主適合異質、分歧多的社會。民主模型要配合社會條件選擇。","refs":[["pol","c4","c4s5"],["pol","c4","c4s2"],["pol","c5","c5s6"]]},
    {"id":"t-plurality","sid":"pol","zh":"相對多數決","en":"plurality","text":"得票最高者當選、不必過半的選舉規則，英美國會採用。單一選區相對多數決又稱領先者當選制（first-past-the-post）。優點是代表與選區聯繫明確，小黨與極端主義難獲席位，容易產生穩定的一黨過半政府；缺點是落選者的選票遭浪費，得票率與席次率不成比例。","refs":[["pol","c6","c6s1"],["pol","c6","c6s5"],["pol","c4","c4s5"]]},
    {"id":"t-public-service-motivation","sid":"adm","zh":"公共服務動機","en":"public service motivation","text":"個人基於公共利益、服務他人與社會責任而投入公共服務的內在動機，被列為激勵內容理論的一種。它說明公部門人員除了薪資與升遷等外在誘因，也可能因使命感與奉獻而努力，所以公部門的激勵設計不能只看金錢。課文僅略提，內涵請對照書本與 c3s4 的整理。它也提醒我們公私部門的差異。","refs":[["adm","c3","c3s4"]]},
    {"id":"t-miles-law","sid":"adm","zh":"邁爾斯定律","en":"Miles' law","text":"組織病象定律之一，原意是「職位決定立場」（where you stand depends on where you sit），人的看法會隨著所處職位改變，用來形容組織社會化造成的本位主義。部門成員傾向從本單位利益看問題，因此協調不易。考試時常和白京生定律、彼得原理、莫非定律一起比較。","refs":[["adm","c7","c7s8"]]},
    {"id":"t-murphy-s-law","sid":"adm","zh":"莫非定律","en":"Murphy's law","text":"組織病象定律之一，指會出錯的事終究會出錯，小問題常釀成大災禍，所以管理要防微杜漸，事先設想風險。常與白京生定律、邁爾斯定律、彼得原理、不稀罕效應、帕金森瑣碎定律、格勒善法則一起考，要分清楚各定律描述的現象，例如格勒善法則是庸才排擠賢才。這些定律的名稱與內容容易混淆。","refs":[["adm","c7","c7s8"]]},
    {"id":"t-defined-contribution","sid":"adm","zh":"確定提撥制","en":"defined contribution, DC","text":"退休金制度的一種，事先確定每月提撥多少，提撥款進入個人專戶，退休時能領多少取決於帳戶累積與投資績效，投資與物價變動的風險由個人承擔，但較能避免少子女化帶來的財政衝擊。相對的確定給付制（DB）事先確定給付金額，風險由基金或政府承擔，領取人增加時易生財務危機。","refs":[["adm","c9","c9s9"]]},
    {"id":"t-participatory-budgeting","sid":"adm","zh":"參與式預算","en":"participatory budgeting","text":"讓公民直接決定部分公共預算用途的制度，著名例子是巴西愉港市。理念與審議民主一致，符合開放政府的透明與參與精神，推動時常需跨局處合作。它是直接民主、以區為範圍，能促進公民學習。成功條件包括首長支持、公民社會能力與財政彈性。各地因地制宜，沒有統一操作流程。","refs":[["adm","c10","c10s1"],["adm","c10","c10s7"],["adm","c13","c13s3"]]},
    {"id":"t-balanced-scorecard","sid":"adm","zh":"平衡計分卡","en":"balanced scorecard, BSC","text":"由卡普蘭與諾頓 1992 年提出，目的是避免只看財務數字，而從四個構面平衡衡量績效：財務、顧客、內部流程、學習與成長。四個構面之間有因果關係：員工學習成長改善流程，流程改善提升顧客滿意，最後反映在財務上。公部門使用時，常把使命或顧客放在較優先的位置。","refs":[["adm","c14","c14s1"]]},
    {"id":"t-total-quality-management","sid":"adm","zh":"全面品質管理","en":"total quality management, TQM","text":"以顧客滿意為導向、全體成員參與、持續改善流程與品質的管理方法。在行政上常與政府再造一起討論。彼得斯的參與模式主張組織扁平化、全面品質管理與團隊，視基層員工為提升效率的重心。它重視事前預防與過程改善，而不是事後檢查，也強調跨部門合作。它因此常與政府再造一起出現在考題。","refs":[["adm","c6","c6s4"],["adm","c14","c14s2"]]},
    {"id":"t-open-government","sid":"adm","zh":"開放政府","en":"open government","text":"比資訊公開更進一步：不只讓人民查得到資訊，更要讓人民參與決策並與政府協力。美國歐巴馬政府 2009 年提出透明、參與、協力三原則，2011 年多國成立開放政府夥伴關係（OGP）。我國自 2019 年起推動開放政府國家行動方案，強調透明、參與、涵容、課責四大精神。","refs":[["adm","c13","c13s3"],["adm","c14","c14s7"]]},
    {"id":"t-bureaucracy","sid":"pol","zh":"官僚組織","en":"Bureaucracy","text":"由層級制度、正式規則和標準化流程組成的組織管理模式，常用於管理政府機關、企業等大型組織。韋伯提出的理想型特徵有層級節制、專業分工、依法辦事、非人情化、依專業能力甄補與永業化。文官的權力來源有戰略位置、常任優勢與專業優勢。墨頓則指出其反功能。這些是分析文官體系的基本概念。","refs":[["pol","c5","c5s10"],["adm","c2","c2s5"],["adm","c2","c2s6"]]},
    {"id":"t-cadre-party","sid":"pol","zh":"幹部型政黨","en":"Cadre party","text":"是指政黨的組織者與領導者為社會上的菁英或議會內的政治人物，這類型的政黨不以吸收大量黨員為目標，甚至需要嚴格審查資格方能入黨。幹部政黨的營運經費則是仰賴特定財力雄厚的企業或菁英所捐獻。此反映出這類型的政黨存在於選舉權尚未普及的國家，吸收黨員非政黨運作的要務，甚至政黨的菁英會向大眾提供意識形態的領導，諸如蘇聯共產黨（Communist Party of the Soviet Union, CPSU）、德國納粹（Nazi Party）、義大利法西斯政黨（Fascist Party）與中國共產黨（Chinese Communist Party）皆為幹部政黨。","refs":[["pol","c6","c6s3"]]},
    {"id":"t-elitism","sid":"pol","zh":"菁英主義","en":"Elitism","text":"認為控制政治、經濟與社會的是少數權力菁英，他們支配公共事務，與社會多數人的意願無關。古典菁英論者包括巴烈圖、莫斯卡與提出寡頭鐵律的米契爾斯；米爾斯則指出美國由企業、軍方與政治三方菁英構成權力菁英。它強調制度位置的重要性，常與多元主義對照。兩者對權力分布的看法正好相反。","refs":[["pol","c2","c2s4"],["pol","c3","c3s5"],["pol","c4","c4s3"]]},
    {"id":"t-perfect-rationality","sid":"adm","zh":"完全理性","en":"perfect rationality","text":"古典經濟學對「經濟人」的假設：決策者擁有完整資訊與計算能力，完全理性、自利，追求效用極大化，因此能找出最佳解。賽蒙認為組織決策受資訊、時間、計算能力與慣例限制，多數決策並非出於完全理性，只能做到有限理性，追求滿意解。這是理性決策途徑的主要批評。它與有限理性是常考的對照。","refs":[["adm","c3","c3s3"],["adm","c6","c6s1"],["adm","c8","c8s4"]]},
    {"id":"t-participatory-democracy","sid":"pol","zh":"參與式民主","en":"Participatory Democracy","text":"又稱激進民主，1970 年代興起，以社群主義為基礎，認為自我發展的平等權利只有在「參與的社會」中才能實現。巴伯在《強勢民主》批評代議民主是弱勢民主，使自由民主淪為保障個人權利的手段；強勢民主則讓人民在互動中把私利轉化為公共善。限制是多在社區層級、出席意願不高。","refs":[["pol","c4","c4s4"],["adm","c11","c11s2"],["pol","c6","c6s7"]]},
    {"id":"t-developmental-state-theory","sid":"pol","zh":"發展型國家理論","en":"Developmental State Theory","text":"主張以國家力量主導後進工業國家的工業化，用來解釋日本、韓國、臺灣、新加坡等東亞國家的經濟奇蹟。代表學者有研究日本通產省的詹鶽（C. Johnson）、研究臺灣的韋德、研究韓國的安士敦。其論點是國家具有相對自主性，能抗拒其他行為者影響，制定有效的產業政策。","refs":[["pol","c2","c2s6"]]},
    {"id":"t-fascism","sid":"pol","zh":"法西斯主義","en":"Fascism","text":"法西斯主義具有一種「反抗特質」（anti-character)，這大多是藉由其反對事物來定義的：它是一種反資本主義、反自由主義、反個人主義與反共產主義等形式。而貫穿法西斯主義的中心思想就是由獨裁者領導強制性的、大一統的、嚴密控制的國家。法西斯主義一詞來自fascio，義大利文中代表一捆，這裡代表著一捆人民，這樣的意象可以追溯到古羅馬，當時這個詞的意象是領導者拿著一捆木頭，而上面插著一把斧頭。法西斯主義的理念是對一位英雄（領導人）的認同是受到責任、榮譽、與自我犧牲所激勵，並準備為其國家或種族的光榮而奉獻終生，且毫無疑問地服從最高領袖。","refs":[["pol","c2","c2s4"],["pol","c3","c3s5"],["pol","c3","c3s3"]]},
    {"id":"t-dictatorship","sid":"pol","zh":"獨裁政治","en":"Dictatorship","text":"相對於民主政治的政府類型，最終統治權由一人或一小部分人掌握。基本原則有主權在一人或小團體手上、政治不平等、沒有大眾諮商、少數統治。極權與威權獨裁的區別在社會控制的領域與程度：威權嚴格控制政治生活，私人領域享有較多自由；極權則徹底控制人們所有層面。這是常考的基本區別。","refs":[["pol","c4","c4s7"]]},
    {"id":"t-cohabitation","sid":"pol","zh":"左右共治","en":"Cohabitation","text":"所謂左右共治，係指在雙首長制國家中，總統與國會多數黨不屬同一黨，總統為了尊重多數治理的民主原則，會任命多數黨黨魁擔任總理，而總統將自己的權力自限於國防與外交，而形成左右共治。法國歷史上曾出現三次左右共治的情形，但隨著2002年修法，令總統大選早於國會大選，使左右共治的機會降低很多。","refs":[["pol","c5","c5s3"],["con","c9","c9s2"],["pol","c5","c5s5"]]},
    {"id":"t-president-parliamentary","sid":"pol","zh":"總統國會制","en":"President-parliamentary","text":"舒加特與凱瑞提出的半總統制次類型，課文也稱總統議會制。總統有權干涉總理與政府組成，可任免閣揆，國會也可倒閣，所以總理同時對總統與國會負責，總統權力較大，例如我國、俄羅斯。總統與國會多數黨不一致時，可能走向分立政府或共治。相對的是總理總統制。這也是我國憲政體制的常見定位。","refs":[["pol","c5","c5s3"]]},
    {"id":"t-unified-government","sid":"pol","zh":"一致政府","en":"Unified government","text":"行政部門與立法部門由同一政黨掌握的狀態，相對的是分立政府。一致政府的立法與施政效能通常較高，因為總統或行政首長與國會多數方向一致，政策容易通過；但也可能因為制衡減弱，責任與監督問題更受關注。在半總統制與總統制的憲政比較中，常用來分析政局穩定。兩者區別在於行政與立法是否同黨。","refs":[["pol","c5","c5s9"]]},
    {"id":"t-the-principles-of-administration-school","sid":"adm","zh":"行政管理學派","en":"The Principles of Administration School","text":"傳統理論時期的學派之一，又稱原理學派，代表人物是費堯與古立克。它從組織上層研究管理的原則與功能，例如古立克的 POSDCORB，把行政看成計畫、組織、用人、指揮、協調、報告、預算七項工作。它與管理技術學派、官僚型模學派合稱科學管理運動。它屬於傳統理論時期的主流。","refs":[["adm","c2","c2s1"],["adm","c2","c2s3"],["adm","c1","c1s3"]]},
    {"id":"t-bureaucratic-model","sid":"adm","zh":"官僚型模","en":"Bureaucratic model","text":"韋伯提出的組織理想型，又稱科層體制，屬傳統時期的學派。六項特點是依法行政、層級節制、對事不對人、專業分工與技術訓練、永業化傾向、依年資和地位給付薪資。它建立在合法權威上。缺點是忽略人的感情與非正式組織、造成本位主義與僵化，也被批評缺乏實證。它對現代組織理論影響深遠。","refs":[["adm","c2","c2s1"],["adm","c2","c2s5"]]},
    {"id":"t-human-relations-school","sid":"adm","zh":"人群關係學派","en":"Human Relations School","text":"由霍桑實驗開啟，奠基者是梅堯，不是傅麗德。它主張工作場所的社會情境會影響生產力，管理者應重視員工感受、溝通與參與，也使修正時期的研究從靜態結構轉向人的行為。批評者譏諷它是「母牛社會學」，就像讓母牛快樂就能多產牛奶，只是用更溫和的手段操控工人。它的貢獻是把人帶回組織研究。","refs":[["adm","c3","c3s1"],["adm","c2","c2s4"],["adm","c8","c8s5"]]},
    {"id":"t-administrative-act","sid":"alaw","zh":"行政處分","en":"administrative act","text":"行政程序法第 92 條：行政機關就公法上具體事件所為之決定或其他公權力措施，而對外直接發生法律效果的單方行政行為。判斷要素是行政機關、公法、具體事件、對外直接生效、單方。對行政處分不服的救濟，原則上是訴願與行政訴訟；公務員則為復審。要與法規命令及事實行為區別。","refs":[["alaw","c1","c1s2"],["alaw","c1","c1s3"],["alaw","c1","c1s4"]]},
    {"id":"t-administrative-rules","sid":"alaw","zh":"行政規則","en":"administrative rules","text":"行政程序法第 159 條：上級機關對下級機關，或長官對屬官，依權限或職權為規範機關內部秩序及運作，所為非直接對外發生法規範效力的一般、抽象規定。它不需法律授權，只有內部效力，但可能經平等原則間接對外。法官不受其拘束（釋字 216 號）。作業要點、注意事項多屬此類。","refs":[["alaw","c1","c1s3"],["alaw","c2","c2s4"],["alaw","c6","c6s1"]]},
    {"id":"t-regulations","sid":"alaw","zh":"法規命令","en":"regulations (legislative rules)","text":"行政程序法第 150 條：行政機關基於法律授權，對多數不特定人民就一般事項所作抽象之對外發生法律效果的規定。它須有法律授權，授權要具體明確，內容不得逾越授權範圍，且應發布。相對的是行政規則。施行細則、「規則」「辦法」通常屬法規命令。與人民權利義務有關的事項常以它規定。","refs":[["alaw","c1","c1s3"],["alaw","c5","c5s1"],["alaw","c6","c6s1"]]},
    {"id":"t-principle-of-proportionality","sid":"alaw","zh":"比例原則","en":"principle of proportionality","text":"國家行為限制人民權利時，手段與目的要相當。憲法依據是第 23 條「必要」，行政程序法第 7 條明定三個子原則：適當性（手段能達成目的）、必要性（選擇侵害最小的手段）、衡量性（損害與利益不得顯失均衡）。典型案例：釋字 744（適當性）、715（必要性）、603（衡量性）。","refs":[["alaw","c4","c4s4"],["alaw","c6","c6s1"],["alaw","c9","c9s1"]]},
    {"id":"t-principle-of-equality","sid":"alaw","zh":"平等原則","en":"principle of equality","text":"憲法第 7 條與行政程序法第 6 條：行政行為非有正當理由，不得為差別待遇。它不是機械的形式平等，而是實質平等，容許合理差別待遇（釋字 485 號）。審查時看目的是否合憲、分類與目的有無合理關聯。第 7 條所列事由是例示，性傾向也受保障（釋字 748 號）。","refs":[["alaw","c6","c6s2"],["adm","c1","c1s4"],["con","c3","c3s2"]]},
    {"id":"t-reservation-of-law","sid":"alaw","zh":"法律保留","en":"reservation of law","text":"依法行政的子原則，又稱積極的依法行政：涉及人民權利或重大事項，行政機關須有法律依據才能行動。憲法依據是第 23 條，中央法規標準法第 5 條亦明列。釋字 443 號建立層級化法律保留：憲法保留、絕對法律保留、相對法律保留、無須法律保留，給付行政的密度較寬鬆。","refs":[["alaw","c2","c2s1"],["alaw","c4","c4s1"],["alaw","c6","c6s2"]]},
    {"id":"t-supremacy-of-law","sid":"alaw","zh":"法律優位","en":"supremacy of law","text":"依法行政的子原則，又稱消極的依法行政：行政行為不得牴觸法律，以及憲法與一般法律原則。規範位階是憲法＞法律＞命令，憲法第 171、172 條為依據；地方自治法規也不得牴觸中央法規。它與法律保留不同：法律優位是不得違法，適用於所有行政行為；法律保留是要有法律依據才能做。","refs":[["alaw","c2","c2s1"],["alaw","c8","c8s2"],["alaw","c9","c9s1"]]},
    {"id":"t-protection-of-legitimate-expectations","sid":"alaw","zh":"信賴保護原則","en":"protection of legitimate expectations","text":"人民對國家法秩序的存續產生信賴並據以安排生活，國家變動時應保護其值得保護的信賴，行政程序法第 8 條亦有明文。要件有三：信賴基礎、信賴表現、信賴值得保護。釋字 525 號肯認它不限具體處分的撤銷或廢止，抽象法規範的變動也適用；純屬主觀期待者不受保護。","refs":[["con","c1","c1s6"],["jur","c12","c12s1"],["alaw","c2","c2s4"]]},
    {"id":"t-principle-of-legal-clarity","sid":"alaw","zh":"法律明確性","en":"principle of legal clarity","text":"涉及人民權利的法律要清楚，但立法不可能鉅細靡遺，可使用不確定法律概念與概括條款。依釋字 432 號，三要件是意義非難以理解、為受規範者所得預見、可經司法審查確認。合憲例如釋字 702 號「有損師道」；違憲例如 636 號「品行惡劣、遊蕩無賴」與 777 號。","refs":[["alaw","c2","c2s2"],["con","c1","c1s6"],["con","c2","c2s2"]]},
    {"id":"t-administration-according-to-law","sid":"alaw","zh":"依法行政","en":"administration according to law","text":"行政行為應受法律及一般法律原則拘束，是法治國原則的核心，行政程序法第 4 條明定。它有兩個子原則：法律優位（消極，不得牴觸）與法律保留（積極，須有依據）。行政機關應主動適用法律，可依自己理解解釋法規，但受上級監督，最終解釋權在法院。這與韋伯官僚制的特徵是不同層次。","refs":[["alaw","c1","c1s1"],["alaw","c2","c2s1"],["alaw","c5","c5s1"]]},
    {"id":"t-administrative-contract","sid":"alaw","zh":"行政契約","en":"administrative contract","text":"行政程序法第 135 條：公法上法律關係得以契約設定、變更或消滅之，但依其性質或法規規定不得締約者除外。它是雙方行為，有別於單方的行政處分，應以書面為之，原則上不需法律明文授權。例如健保署與特約醫事機構的合約（釋字 533 號），爭議走行政訴訟。行政機關也可依法與人民締約。","refs":[["alaw","c1","c1s2"],["alaw","c1","c1s4"],["alaw","c5","c5s1"]]},
    {"id":"t-factual-act","sid":"alaw","zh":"事實行為","en":"factual act","text":"行政機關不以發生法律效果為目的，而直接產生事實結果的行為，例如道路維修、資訊提供、勸導、資料蒐集與部分強制措施。它與行政處分的差別在於不對外發生規制效力，因此救濟途徑通常不是撤銷訴訟，而是依行政訴訟法請求一般給付或確認。違法造成損害時可能生國家賠償問題。","refs":[["alaw","c1","c1s4"],["alaw","c7","c7s1"],["alaw","c9","c9s1"]]},
    {"id":"t-administrative-guidance","sid":"alaw","zh":"行政指導","en":"administrative guidance","text":"行政程序法第 165 條：行政機關在其職權或所掌事務範圍內，為實現一定之行政目的，以輔導、協助、勸告、建議或其他不具法律上強制力之方法，促請特定人為一定作為或不作為之行為。它不具強制力，相對人明確拒絕時應停止，且不得據此為不利處置，屬事實行為的一種。","refs":[["alaw","c5","c5s1"],["alaw","c7","c7s1"],["alaw","c9","c9s2"]]},
    {"id":"t-indeterminate-legal-concept","sid":"alaw","zh":"不確定法律概念","en":"indeterminate legal concept","text":"法律用語具有多義性、未具體規定的概念，有確定的核心與模糊的外圍，例如「有礙公共安全」「情節重大」，多出現在構成要件。口訣是構成要件看不確定法律概念，法律效果看行政裁量。法院原則上全面審查，但具高度專業或屬人性者，例如考試評分，有判斷餘地，採低密度審查。","refs":[["alaw","c2","c2s3"],["con","c1","c1s6"],["con","c2","c2s1"]]},
    {"id":"t-general-ruling","sid":"alaw","zh":"一般處分","en":"general ruling","text":"行政程序法第 92 條第 2 項：決定或措施之相對人雖非特定，而依一般性特徵可得確定其範圍者，為一般處分；有關公物之設定、變更、廢止或其一般使用者，亦同。它仍是行政處分，要與抽象的法規命令區別。一般處分經公告或刊登政府公報、新聞紙者，得不記明理由。這是常考的區別。","refs":[["alaw","c5","c5s4"],["alaw","c5","c5s2"],["alaw","c7","c7s1"]]},
    {"id":"t-delegated-matters","sid":"alaw","zh":"委辦事項","en":"delegated matters","text":"地方制度法第 2 條：地方自治團體依法律、上級法規或規章規定，在上級政府指揮監督下，執行上級政府交付辦理之非屬該團體事務，而負其行政執行責任之事項。上級可就適法性與合目的性監督（釋字 498、553 號）。與自治事項的區分實益在監督強度與經費負擔。地方可訂委辦規則。","refs":[["alaw","c3","c3s6"],["alaw","c3","c3s3"],["con","c13","c13s2"]]},
    {"id":"t-self-governance-matters","sid":"alaw","zh":"自治事項","en":"self-governance matters","text":"地方制度法第 2 條：地方自治團體依憲法或本法規定，得自為立法並執行，或法律規定應由該團體辦理並負其政策規劃及執行責任之事項。上級原則上只作適法性監督（釋字 498、553 號），不及於合目的性。里長延選是例子。地方可就自治事項制定自治條例或自治規則。","refs":[["alaw","c3","c3s6"],["adm","c12","c12s3"],["con","c13","c13s2"]]},
    {"id":"t-independent-agency","sid":"alaw","zh":"獨立機關","en":"independent agency","text":"中央行政機關組織基準法第 3 條：依法獨立行使職權、自主運作，除法律另有規定外，不受其他機關指揮監督的合議制機關，例如 NCC、公平會、中選會。成員的任期與資格有法律保障，同黨籍不得超過一定比例。釋字 613 號指出行政院對其仍應有人事決定權，不能實質剝奪。","refs":[["alaw","c2","c2s3"],["alaw","c3","c3s1"],["adm","c7","c7s6"]]},
    {"id":"t-administrative-corporation","sid":"alaw","zh":"行政法人","en":"administrative corporation","text":"依行政法人法，由中央目的事業主管機關為執行特定公共任務，依法律設立的公法人。適用於不適合由行政機關辦理、又不宜交給民間的專業公共事務，例如國家表演藝術中心。它具獨立法人格與較大的人事、財務彈性，並受監督機關監督，是我國組織改造「四化」中的行政法人化。","refs":[["alaw","c3","c3s1"],["adm","c6","c6s5"],["adm","c7","c7s6"]]},
    {"id":"t-state-compensation","sid":"alaw","zh":"國家賠償","en":"state compensation","text":"憲法第 24 條為基礎，國家賠償法第 2 條規定公務員執行職務行使公權力，因故意或過失不法侵害人民權利，或怠於執行職務時，國家應負賠償責任；第 3 條則是公共設施瑕疵。原則由普通法院民事庭審理，須先以書面向賠償義務機關請求協議。怠於執行的要件見釋字 469 號。","refs":[["alaw","c1","c1s2"],["alaw","c3","c3s2"],["alaw","c4","c4s1"]]},
    {"id":"t-human-dignity","sid":"con","zh":"人性尊嚴","en":"human dignity","text":"人權的價值基礎。康德主張人本身即是目的，不能只被當作工具；德國聯邦憲法法院據此發展出客體公式：人不得被貶低為國家統治的客體，也就是不得把人當作物或達成目的的手段。我國憲法未明文，大法官在解釋中肯認其為憲法核心價值，增修條文第 10 條也提到維護婦女人格尊嚴。","refs":[["con","c2","c2s3"],["con","c6","c6s1"],["con","c1","c1s2"]]},
    {"id":"t-university-autonomy","sid":"con","zh":"大學自治","en":"university autonomy","text":"憲法第 11 條講學自由的制度性保障，內容包括研究自由、教學自由與學習自由。大學可就教學研究、內部組織與學生管理自主決定，國家可依法監督但不得干預。重要解釋：釋字 380 號（共同必修科目）、450 號（軍訓室）違憲；563 號（退學）、626 號（入學資格）合憲。","refs":[["con","c2","c2s1"],["alaw","c1","c1s4"],["con","c5","c5s5"]]},
    {"id":"t-analogical-application","sid":"jur","zh":"類推適用","en":"analogical application","text":"法律對某事項未規定時，援引性質相類似事項的規定加以適用，屬於填補法律漏洞的方法，依「相同事物應為相同處理」的法理。民事可依習慣、法理補充並可類推適用（民法第 1 條）；刑事則禁止不利被告的類推，這是罪刑法定原則的要求。它與擴張解釋不同，後者仍在文義範圍內。","refs":[["jur","c5","c5s1"],["jur","c5","c5s4"],["jur","c2","c2s5"]]},
    {"id":"t-action-for-mandatory-injunction","sid":"alaw","zh":"課予義務訴訟","en":"action for mandatory injunction","text":"行政訴訟法第 5 條：人民申請行政機關作成處分，機關怠為處分或駁回，經訴願程序後，請求法院命機關作成特定內容處分的訴訟。判斷基準時原則為事實審言詞辯論終結時。必須有公法上請求權，例如 111 年憲判字第 20 號認為本國配偶不能為外籍配偶提起。這是要件上的關鍵。","refs":[["alaw","c1","c1s3"],["alaw","c5","c5s3"],["alaw","c7","c7s3"]]},
    {"id":"t-action-for-revocation","sid":"alaw","zh":"撤銷訴訟","en":"action for revocation","text":"行政訴訟法第 4 條：人民因違法行政處分，認為損害其權利或法律上利益，經訴願程序後，請求法院撤銷處分的訴訟，適用於負擔處分，例如課稅處分、罰鍰。判斷是否違法，原則以處分作成時的事實與法規為準。原告須主張權利受損，只受事實上利益影響的第三人不行。這是訴訟權能的要求。","refs":[["alaw","c1","c1s3"],["alaw","c7","c7s2"],["alaw","c7","c7s6"]]},
    {"id":"t-literal-interpretation","sid":"jur","zh":"文義解釋","en":"literal interpretation","text":"依條文的日常字義或法律用語確定其意義的解釋方法，是法律解釋的起點，也是其他解釋方法的界限。例如身體語言算不算「言論」。各條文單獨解釋可能前後矛盾，就要用體系解釋對照前後條文；還可再參考歷史解釋與目的解釋。憲法解釋的合憲性解釋則是另一種限縮法律適用的方法。","refs":[["jur","c5","c5s2"],["con","c1","c1s4"],["jur","c5","c5s4"]]},
    {"id":"t-purposive-interpretation","sid":"jur","zh":"目的解釋","en":"purposive interpretation","text":"從法律規範所要實現的目的來解釋條文的方法。文義有多種可能時，選擇最能達成立法目的的解釋。它與文義解釋、體系解釋、歷史解釋並列，常用於處理條文無法直接回答的問題。目的又可分為立法者主觀的目的與法律客觀的目的；後者會隨社會變遷調整，適用時要留意。解釋結果也不能超出文義。","refs":[["jur","c5","c5s2"],["con","c1","c1s4"]]},
    {"id":"t-historical-interpretation","sid":"jur","zh":"歷史解釋","en":"historical interpretation","text":"探求立法者或制憲者原意，或依歷史發展解釋條文的方法，常依立法理由、議事紀錄等資料判斷，例如日本憲法第 9 條的討論。陳淳文老師指出中華民國憲法的制憲歷史都在中國，是「沒有歷史的憲法」，歷史解釋較難運用。它與文義、體系、目的解釋是常見的解釋方法。它也有助於理解條文脈絡。","refs":[["jur","c5","c5s2"],["con","c1","c1s4"]]},
    {"id":"t-personal-liberty","sid":"con","zh":"人身自由","en":"personal liberty","text":"憲法第 8 條保障的權利，逮捕拘禁時應告知理由，並至遲於 24 小時內移送法院審問，採憲法保留。非由法定機關不得逮捕拘禁，非由法院不得審問處罰。重要解釋：384 號（實質正當法律程序）、392 號（羈押權屬法官）、588 號（管收）、690 號（強制隔離合憲）、708 號（外國人收容）。","refs":[["con","c2","c2s1"],["pol","c8","c8s1"],["pol","c8","c8s2"]]},
    {"id":"t-emergency-decree","sid":"con","zh":"緊急命令","en":"emergency decree","text":"依增修條文第 2 條第 3 項，總統為避免國家或人民遭遇緊急危難或應付財政經濟重大變故，得經行政院會議決議發布，不受憲法第 43 條限制，須於發布後 10 日內提交立法院追認，不同意即失效。依釋字 543 號，原則上不得再授權補充，立法院只能就當否決議，不得變更內容。","refs":[["con","c8","c8s2"],["pol","c5","c5s5"],["alaw","c1","c1s3"]]},
    {"id":"t-administrative-penalty","sid":"alaw","zh":"行政罰","en":"administrative penalty","text":"行政罰法第 1、2 條：對違反行政法上義務的行為，所科處的罰鍰、沒入或其他種類裁罰性不利處分，例如限制或禁止行為、剝奪或消滅資格權利、影響名譽、警告性處分。不包括刑罰與懲戒。重要原則有處罰法定、從新從輕（第 5 條）、有責性（第 7 條）、一行為不二罰（第 24 條）。","refs":[["alaw","c4","c4s4"],["alaw","c10","c10s1"],["alaw","c10","c10s3"]]},
    {"id":"t-right-to-claim","sid":"alaw","zh":"請求權","en":"right to claim","text":"要求特定人為或不為一定行為的權利。公法上請求權的消滅時效規定在行政程序法第 131 條：除法律另有規定外，行政機關的請求權 5 年不行使而消滅，人民的請求權為 10 年。時效完成後權利當然消滅。課予義務訴訟也以人民有公法上請求權為前提；反射利益則不能請求。","refs":[["alaw","c2","c2s1"],["alaw","c5","c5s2"],["alaw","c12","c12s3"]]},
    {"id":"t-representative-bureaucracy","sid":"adm","zh":"代表性官僚","en":"Representative bureaucracy","text":"指行政機關的人員組成應適度反映社會母體結構，使不同族群、性別與地區都有代表，以公平回應多元需求。金斯萊（J. D. Kingsley）1944 年在《代表性官僚制》提出，是巴頓（R. Barton）所列行政人員五角色之一，也是調和官僚與民主的方法，屬新公共行政與民主行政的主張；美國弱勢優惠行動是同方向的作法。它也被列為內部非正式的行政責任途徑。易混淆：不是替某一政黨或選區發言，也不是俘虜性組織（機關成為利益團體的代理人）。","refs":[["adm","c5","c5s1"],["adm","c5","c5s2"],["adm","c5","c5s4"],["adm","c7","c7s8"],["adm","c9","c9s1"],["adm","c13","c13s2"]]},
    {"id":"t-british-disease","sid":"pol","zh":"英國病","en":"British disease","text":"指 1960 年代以後英國經濟停滯、社會問題同時出現的現象；1960 至 1970 年代英國勞資糾紛頻繁、成長不振，也被稱為「歐洲病夫」（Sick man of Europe）。背景是戰後的英式社會主義：艾德禮（C. Attlee）工黨政府在 1945 至 1951 年間把煤礦、鐵路、鋼鐵、電力等基幹產業收歸國有，並依 1942 年貝佛里奇（W. Beveridge）報告建立「從搖籃到墳墓」的社會保障，1948 年成立國民保健服務（NHS）。1970 年代英國遭遇石油危機，通膨一度超過 20%，1976 年向國際貨幣基金借款，1978 至 1979 年的「不滿之冬」大罷工重挫工黨政府，柴契爾（M. Thatcher）隨後勝選。成因有爭議：新右派認為社會保障負擔過重、國民工作意願下降、國有企業與工會滋生既得利益，因此主張民營化、削減福利與限制工會；另一種看法認為石油危機等全球衝擊與長期的工業競爭力下滑同樣重要，當時的危機也有被誇大的成分。考試上常作為新右派興起的背景。","refs":[["pol","c3","c3s4"]]},
    {"id":"t-social-darwinism","sid":"pol","zh":"社會達爾文主義","en":"Social Darwinism","text":"把達爾文（C. Darwin）1859 年《物種起源》的演化論搬到人類社會的一類主張，認為個人、民族或種族之間也是物競天擇、適者生存，強者勝出是自然法則。「適者生存」（survival of the fittest）一語出自史賓賽（H. Spencer），不是達爾文最先提出。它有不同的用法：史賓賽與美國的孫末楠（W. G. Sumner）用來主張放任資本主義、反對政府救濟；歐美列強用來替帝國擴張與種族階層辯護；清末嚴復譯《天演論》則用來警示中國「物競天擇」的亡國危機，轉為救亡圖強的動力。法西斯主義把競爭單位換成民族與種族，視鬥爭與戰爭為民族強盛的必經之路，納粹再結合優生學、強制絕育與「生存空間」（Lebensraum）的主張。批評者指出，演化論描述生物如何適應環境，不能推出誰比較優秀或誰應該統治（由「是」推不出「應該」）；現代生物學也不支持種族優劣之說。這個名稱本身也多半是批評者使用的標籤，當年被歸類的人不一定這樣自稱。","refs":[["pol","c3","c3s5"]]},
    {"id":"t-great-purge","sid":"pol","zh":"大清洗","en":"Great Purge（Great Terror）","text":"1936 至 1938 年間，蘇聯在史達林（J. Stalin）主導下以肅清叛徒與間諜為名發動的大規模鎮壓，1934 年列寧格勒黨部書記基洛夫遇刺常被視為導火線。執行者是秘密警察內務人民委員部（NKVD），高峰期由葉若夫主持，所以俄文也稱「葉若夫時期」。主要內容有三：一是三次公開的「莫斯科審判」，季諾維也夫、卡米涅夫、布哈林等革命元老認罪後遭處決；二是清洗紅軍高層，包括元帥圖哈切夫斯基；三是擴及黨政幹部、知識分子、少數民族與一般民眾。依蘇聯解密檔案，1937 至 1938 年約 150 萬人被捕、約 70 萬人被處決，更多人送進勞改營（古拉格），實際數字學界仍有不同估計。當時官方宣稱是粉碎反革命陰謀；赫魯雪夫（N. Khrushchev）1956 年的秘密報告才在黨內批判史達林的個人崇拜與濫權。動機的解釋也有爭論：有人強調史達林鞏固權力與個人猜疑，有人強調地方黨組織的鬥爭與戰爭將至的恐慌。考點上常用來說明列寧主義權力缺乏制衡的批評、列寧與史達林的斷裂論或連續論，也是極權主義恐怖統治的典型例子。","refs":[["pol","c3","c3s2"]]},
    {"id":"t-bureaucratic-pilgrimage","sid":"pol","zh":"朝聖之旅（官僚朝聖）","en":"Bureaucratic pilgrimage","text":"安德森（B. Anderson）在《想像的共同體》解釋美洲民族意識起源時用的比喻。宗教朝聖讓素不相識的信徒走同一條路、前往同一個聖地，因而感受到彼此屬於同一個共同體；官員的調任升遷也有類似作用。西班牙美洲殖民地出生的歐裔菁英稱為克里奧爾人（Creole），語言、宗教、祖先都與母國相同，卻因為出生在殖民地而受歧視：他們當官一輩子只能在自己的殖民行政區內調動，最高到區內首府，幾乎不可能調回母國任職。一路上遇到的同僚都是處境相同的同鄉，於是產生「為什麼我們會一起在這裡」的自覺，覺得自己與母國出生的官員不同。再加上當地報紙只報導本區的消息，讀者逐漸把這個行政區想像成自己的共同體，行政區的範圍後來也成了新國家的邊界。安德森因此主張現代民族意識最早出現在美洲，而不是歐洲。後來亞非殖民地的學生到殖民地首府受教育，同樣形成類似的「教育朝聖」，培養出反殖民的民族主義者。","refs":[["pol","c3","c3s5"]]},
    {"id":"t-cultural-nationalism","sid":"pol","zh":"文化民族主義","en":"Cultural nationalism","text":"認為民族是由共同的文化與語言定義的共同體，而不只是政治組織或法律上的公民集合。它強調民族有自己的主體性與自主發展，由下而上形成，不是外界或上層菁英選擇的結果，因此帶有排他、封閉的傾向。它與血統論不完全相同：標準是文化而不是血緣，孩子即使與父母血緣相同，在別的文化中長大，也要學會這套文化才算同一民族；反過來說，外來者理論上可以透過同化加入，只是門檻很高。與它相對的是公民民族主義（civic nationalism），以認同共同的憲政價值與公民身分定義民族，新移民因此可以加入。110 年地特考「接納新移民成為該國公民」挑戰哪個概念，答案就是文化民族主義。支持者認為它能保存語言與文化認同，凝聚社會；批評者認為它難以接納新移民，也可能成為排外的理由。公民民族主義者主張認同憲政價值就足以形成共同體，文化民族主義者則認為這樣的認同太薄、凝聚力不足。","refs":[["pol","c3","c3s5"],["pol","c2","c2s3"]]},
    {"id":"t-drunk-driving-penalties","sid":"alaw","zh":"酒駕的行政罰與刑罰","en":"Penalties for drunk driving","text":"酒駕同時涉及刑罰與行政罰，是行政罰法第 26 條刑事優先的典型例子。吐氣酒精濃度 0.15 mg/L 或血液 0.03% 以上，依道路交通管理處罰條例第 35 條處罰鍰（汽車 3 萬至 12 萬元、機車 1.5 萬至 9 萬元），並吊扣駕照、當場移置保管車輛。吐氣 0.25 mg/L 或血液 0.05% 以上，構成刑法第 185 條之 3 不能安全駕駛罪，移送地檢署；未達 0.25 但有其他情事足以認定不能安全駕駛（例如蛇行、撞車），也可能成罪。判刑確定就不再罰鍰，但吊扣、吊銷駕照屬其他種類行政罰，監理機關仍得裁處；不起訴、緩起訴確定則回到罰鍰。坊間法律網站整理的量刑傾向（不是法定標準，個案還看前科與是否肇事）：0.25–0.40 初犯多判拘役並可易科罰金；0.40–0.60 可能判短期有期徒刑，緩刑機率較高；0.60 以上較可能判有期徒刑、較難緩刑。考試只考法定門檻。","refs":[["alaw","c10","c10s2"]]},
    {"id":"t-offset-of-fines","sid":"alaw","zh":"緩起訴處分金與義務勞務扣抵罰鍰","en":"Offsetting administrative fines","text":"行政罰法第 26 條第 3、4 項：一行為同時涉及刑事與行政罰，刑事部分緩起訴或緩刑，並附帶命行為人向公庫或公益團體支付一定金額或提供義務勞務者，已付金額或勞務應從之後裁處的罰鍰中扣抵；勞務按最初裁處時每小時基本工資乘以時數折算，呼應釋字第 751 號。緩起訴處分金不是刑罰的罰金，所以不是「罰金加罰鍰」。算例：甲酒駕測得 0.3 mg/L，獲緩起訴並支付 5 萬元，監理機關之後處罰鍰 6 萬元，只要再繳 1 萬元；處分金超過罰鍰就不必再繳（條文只規定扣抵，沒有規定退還，多付的部分依條文推論不退）。若改命義務勞務 40 小時，假設基本工資每小時 200 元，折 8,000 元，罰鍰 6 萬只要再繳 5 萬 2 千元；勞務價值超過罰鍰，或機關最後沒有處罰鍰，依條文推論國家不會倒找錢（條文未明文）。若甲被判刑而沒有緩刑，依第 1 項不再罰鍰，只另吊扣或吊銷駕照。","refs":[["alaw","c10","c10s2"]]},
    {"id":"t-social-order-penalties","sid":"alaw","zh":"社會秩序維護法的處罰","en":"Penalties under the Social Order Maintenance Act","text":"社會秩序維護法（社維法）處罰妨害安寧秩序、善良風俗等輕微違序行為，處罰種類有拘留、勒令歇業、停止營業、罰鍰、沒入、申誡。裁處分兩條路：專處或選處罰鍰、申誡，以及併宣告或單獨宣告沒入的案件，由警察機關訊問後直接作成處分書（第 43 條），類似開單；拘留、勒令歇業、停止營業，警察機關要移送地方法院簡易庭裁定（第 45 條）。拘留是社維法特有、拘束人身自由的處罰，1 日以上 3 日以下，加重最多 5 日。和行政罰的關係：一行為違反社維法及其他行政法上義務，已裁處拘留者不再處罰鍰（行政罰法第 24 條第 3 項）。和刑罰的關係：釋字第 808 號認為行為人已受刑事制裁，又依社維法處罰鍰，違反一罪不二罰；停止營業、勒令歇業、沒入則不違反。","refs":[["alaw","c10","c10s2"]]},
  ],
  people: [
    {"id":"p-weber","sid":"adm","name":"韋伯","en":"M. Weber","role":"德國社會學家，官僚型模學派代表","theories":[{"t":"官僚型模","n":"又稱科層體制，研究組織結構的基本條件與理想型態。它是理想型（ideal type），是從現實抽取、作為分析比較基準的概念模型，不是對現實的描述。","refs":[["adm","c2","c2s5"]]},{"t":"權威三類型","n":"傳統性權威、魅力型權威、法理型權威。"},{"t":"常任文官的角色","n":"現代國家真正讓政府發生效力的是日常行政事務，而這些掌握在公務員手中，所以常任文官是真正的治理者之一。","refs":[["adm","c5","c5s2"]]}],"refs":[["adm","c2","c2s1"],["adm","c4","c4s4"],["adm","c8","c8s1"],["pol","c1","c1s5"],["pol","c2","c2s1"],["pol","c5","c5s10"]]},
    {"id":"p-marx","sid":"pol","name":"馬克思","en":"K. Marx","role":"共產主義理論家，與恩格斯共同提出","theories":[{"t":"唯物史觀","n":"歷史演變由物質條件決定。生產力改變，生產關係也隨之改變；經濟是下層建築，政治、法律、文化是上層建築，下層決定上層。","refs":[["pol","c3","c3s2"]]},{"t":"階級理論","n":"每個時代都有擁有生產工具的階級與被支配階級，階級關係是理解政治的基礎。","refs":[["pol","c3","c3s2"]]}],"refs":[["pol","c3","c3s3"],["pol","c3","c3s4"],["pol","c4","c4s8"],["pol","c7","c7s2"]]},
    {"id":"p-aristotle","sid":"pol","name":"亞里斯多德","en":"Aristotle","role":"古希臘哲學家","theories":[{"t":"人是群居動物","n":"不需要生活在社會中的，不是神祇便是野獸。常作為「有社會，斯有法律」的引述。","refs":[["jur","c1","c1s1"]]},{"t":"政治是首要科學","n":"被視為把政治當成最高、首要學問的古典代表。"}],"refs":[["jur","c1","c1s3"],["jur","c5","c5s3"],["pol","c1","c1s1"],["pol","c1","c1s4"],["pol","c2","c2s1"],["pol","c4","c4s7"]]},
    {"id":"p-rawls","sid":"adm","name":"羅爾斯","en":"J. Rawls","role":"美國哲學家，《正義論》（1971）作者","theories":[{"t":"正義論","n":"在原初立場與無知之幕下選出正義原則。第一是平等自由原則；第二處理社會經濟不平等，須符合公平機會平等與差異原則（使最不利者獲得最大利益）。","refs":[["adm","c13","c13s1"]]},{"t":"社會公平的哲學基礎","n":"被視為行政倫理與公平價值的核心理論。","refs":[["adm","c1","c1s4"]]}],"refs":[["pol","c3","c3s1"],["pol","c3","c3s4"],["pol","c8","c8s1"]]},
    {"id":"p-huntington","sid":"pol","name":"杭廷頓","en":"S. P. Huntington","role":"美國政治學者，《第三波》作者","theories":[{"t":"三波民主化","n":"第一波 1828–1926，第一波回潮 1922–1942；第二波 1943–1962，之後也有回潮；第三波始於 1974 年。每一波之後都有回潮。","refs":[["pol","c4","c4s2"]]}],"refs":[["pol","c4","c4s7"],["pol","c4","c4s8"],["pol","c7","c7s2"],["pol","c9","c9s2"]]},
    {"id":"p-montesquieu","sid":"con","name":"孟德斯鳩","en":"Montesquieu","role":"法國思想家，《論法的精神》作者","theories":[{"t":"三權分立","n":"為防止權力集中侵害人民，提出行政、立法、司法三權分立。","refs":[["con","c1","c1s3"]]}],"refs":[["jur","c12","c12s1"],["jur","c2","c2s5"],["pol","c5","c5s2"],["pol","c8","c8s1"]]},
    {"id":"p-hobbes","sid":"pol","name":"霍布斯","en":"T. Hobbes","role":"英國思想家，《巨靈》作者","theories":[{"t":"社會契約與絕對主權","n":"從自然狀態推出社會契約與強大的主權者。","refs":[["pol","c1","c1s4"]]},{"t":"法實證主義先驅","n":"常被視為分析實證法學思想的先驅。","refs":[["jur","c1","c1s3"]]}],"refs":[["pol","c2","c2s1"],["pol","c2","c2s7"]]},
    {"id":"p-simon","sid":"adm","name":"賽蒙","en":"H. A. Simon","role":"美國學者，修正時期決策理論代表","theories":[{"t":"效率觀點的行政定義","n":"公共行政是如何建構與操作組織，以便有效率地完成工作。","refs":[["adm","c1","c1s3"]]},{"t":"決策理論與有限理性","n":"人的理性有限，決策追求滿意而非最佳。"},{"t":"組織平衡論","n":"與巴納德同主張個人利益與組織利益相互平衡。","refs":[["adm","c3","c3s1"]]}],"refs":[["adm","c2","c2s1"],["adm","c3","c3s2"],["adm","c3","c3s3"],["adm","c4","c4s4"],["adm","c8","c8s1"],["adm","c8","c8s4"]]},
    {"id":"p-locke","sid":"pol","name":"洛克","en":"J. Locke","role":"英國思想家，社會契約論者（不是目標設定理論的 E. A. Locke）","theories":[{"t":"信託理論","n":"人民把權力委託給政府，建立在信任關係上；信任破裂，人民可收回權力。","refs":[["con","c1","c1s3"]]},{"t":"社會契約說","n":"與霍布斯、盧梭同為社會契約論代表，人權思想奠基於此。","refs":[["pol","c1","c1s4"]]}],"refs":[["pol","c2","c2s1"],["pol","c3","c3s1"],["pol","c8","c8s1"]]},
    {"id":"p-dahl","sid":"pol","name":"道爾","en":"R. A. Dahl","role":"美國政治學者，多元主義代表","theories":[{"t":"多元主義與《誰在統治？》","n":"1961 年研究紐哈芬市決策，發現不同議題由不同團體主導，沒有單一菁英通吃。","refs":[["pol","c2","c2s4"]]}],"refs":[["adm","c13","c13s3"],["pol","c4","c4s1"],["pol","c4","c4s3"]]},
    {"id":"p-easton","sid":"pol","name":"伊斯頓","en":"D. Easton","role":"政治學者，系統理論代表","theories":[{"t":"政治系統論","n":"環境的需求與支持是投入，決策與政策是產出，結果再經回饋影響下一輪投入。"},{"t":"政治的定義","n":"政治是價值的權威性分配；公共政策是政府對整個社會所做的權威性價值分配。","refs":[["adm","c11","c11s1"]]}],"refs":[["adm","c1","c1s3"],["pol","c1","c1s1"],["pol","c1","c1s3"],["pol","c1","c1s4"],["pol","c2","c2s4"],["pol","c2","c2s5"]]},
    {"id":"p-wilson","sid":"adm","name":"威爾遜","en":"W. Wilson","role":"行政學之父，曾任美國總統（不是管制政治的 J. Q. Wilson）","theories":[{"t":"〈行政的研究〉與政治行政二分","n":"1887 年發表，被視為行政學的起點，主張政治與行政二分。","refs":[["adm","c1","c1s1"]]}],"refs":[["adm","c2","c2s1"],["adm","c2","c2s2"],["pol","c5","c5s6"],["pol","c9","c9s1"]]},
    {"id":"p-maslow","sid":"adm","name":"馬斯洛","en":"A. H. Maslow","role":"美國心理學者，激勵內容理論代表","theories":[{"t":"需求層級理論","n":"1943 年提出，由低而高為生理、安全、愛（社會歸屬）、尊榮感、自我實現。1969 年再發表〈Z 理論〉增補。","refs":[["adm","c3","c3s4"]]}],"refs":[["adm","c3","c3s1"],["adm","c4","c4s4"]]},
    {"id":"p-almond","sid":"pol","name":"阿蒙","en":"G. A. Almond","role":"美國政治學者，比較政治與政治文化代表","theories":[{"t":"結構功能論","n":"政治學上結構功能論的代表，以結構與功能分析政治體系。","refs":[["pol","c2","c2s5"]]},{"t":"《公民文化》","n":"與佛巴比較五國，區分地域型、臣屬型、參與型三種政治文化。","refs":[["pol","c7","c7s1"]]}]},
    {"id":"p-shugart","sid":"pol","name":"舒加特","en":"M. S. Shugart","role":"美國政治學者，與凱瑞研究半總統制","theories":[{"t":"半總統制兩次類型","n":"總理總統制：閣揆只對國會負責，總統不能自行免職。總統議會制：閣揆同時對總統與國會負責。","refs":[["pol","c5","c5s3"]]}],"refs":[["pol","c5","c5s5"]]},
    {"id":"p-verba","sid":"pol","name":"佛巴","en":"S. Verba","role":"美國政治學者","theories":[{"t":"《公民文化》","n":"與阿蒙合著，比較美、英、德、義、墨西哥五國的政治文化。","refs":[["pol","c7","c7s1"]]},{"t":"參與方式比較","n":"與奈伊（N. H. Nie）比較投票、競選、社區活動等，依衝突強度、主動性與合作程度區分。","refs":[["pol","c7","c7s2"]]}]},
    {"id":"p-fayol","sid":"adm","name":"費堯","en":"H. Fayol","role":"法國管理學者，行政管理學派代表","theories":[{"t":"行政管理學派","n":"傳統時期學派之一，從上而下研究組織與管理原則；與古立克同列。","refs":[["adm","c2","c2s1"]]}],"refs":[["adm","c2","c2s2"],["adm","c2","c2s3"],["adm","c4","c4s4"]]},
    {"id":"p-lasswell","sid":"adm","name":"拉斯威爾","en":"H. D. Lasswell","role":"政策科學之父","theories":[{"t":"政策科學","n":"1951 年與賴納合編《政策科學》，主張以解決問題為導向、跨學科，並明白承認價值。","refs":[["adm","c11","c11s1"]]}],"refs":[["pol","c1","c1s1"]]},
    {"id":"p-austin","sid":"jur","name":"奧斯丁","en":"J. Austin","role":"英國法學家，分析實證法學奠基者","theories":[{"t":"法律是主權者的命令","n":"師承邊沁，區分「法律是什麼」與「法律應當是什麼」；法律主權說認為主權是法律上最高的命令者。","refs":[["jur","c1","c1s3"]]}],"refs":[["pol","c2","c2s7"]]},
    {"id":"p-denhardt","sid":"adm","name":"丹哈特","en":"R. B. Denhardt","role":"美國行政學者（不是研究倫理的 K. G. Denhardt）","theories":[{"t":"回應觀點","n":"公共行政是民眾追求社會價值變遷過程中的管理，須配合民主社會並回應需求。","refs":[["adm","c1","c1s3"]]}],"refs":[["adm","c3","c3s3"]]},
    {"id":"p-peters","sid":"adm","name":"彼得斯","en":"B. G. Peters","role":"美國行政學者，《政府的未來治理模式》作者（不是《追求卓越》的 T. J. Peters）","theories":[{"t":"四種治理模式","n":"市場模式、參與模式、彈性化模式、解制模式，用以取代傳統官僚。","refs":[["adm","c6","c6s4"]]}],"refs":[["adm","c9","c9s7"]]},
    {"id":"p-machiavelli","sid":"pol","name":"馬基維利","en":"N. Machiavelli","role":"義大利思想家，《君王論》作者","theories":[{"t":"政治與道德分離","n":"《君王論》把政治從道德中分離。","refs":[["pol","c1","c1s4"]]}]},
    {"id":"p-bodin","sid":"pol","name":"布丹","en":"J. Bodin","role":"法國思想家","theories":[{"t":"主權概念","n":"最早系統提出主權，認為主權是國家在公民與臣民之上的最高權力，不受法律限制且永久。","refs":[["pol","c2","c2s7"]]}]},
    {"id":"p-salamon","sid":"adm","name":"薩拉門","en":"L. M. Salamon","role":"美國學者，非營利組織研究者","theories":[{"t":"非營利組織的特徵","n":"正式組織、民間性、不分配盈餘、自主管理、志願性、公益性。可有盈餘，但不能分配。","refs":[["adm","c6","c6s3"]]}]},
    {"id":"p-peters-t","sid":"adm","name":"彼得斯","en":"T. J. Peters","role":"《追求卓越》作者之一，與瓦特曼合著（不是治理模式的 B. G. Peters）","theories":[{"t":"《追求卓越》","n":"組織文化研究風潮的代表作。","refs":[["adm","c7","c7s4"]]}]},
    {"id":"p-wilson-j","sid":"adm","name":"威爾森","en":"J. Q. Wilson","role":"美國學者（不是總統 W. Wilson）","theories":[{"t":"管制政治四類","n":"依成本與利益集中或分散，分為利益團體政治、顧客政治、企業家政治、多數政治。","refs":[["adm","c11","c11s5"]]}]},
    {"id":"p-denhardt-k","sid":"adm","name":"丹哈特","en":"K. G. Denhardt","role":"美國學者，研究行政倫理（不是 R. B. Denhardt）","theories":[{"t":"行政倫理三基礎","n":"榮譽、仁慈與正義；「品質」不在其中。","refs":[["adm","c13","c13s1"]]}]},
    {"id":"p-barnard","sid":"adm","name":"巴納德","en":"C. I. Barnard","role":"美國管理學者，修正時期代表","theories":[{"t":"權威接受論","n":"權力大小視部屬對上級的接受程度而定，不只看職位高低。","refs":[["adm","c3","c3s1"]]},{"t":"組織平衡論","n":"個人利益與組織利益相互平衡。","refs":[["adm","c3","c3s1"]]}],"refs":[["adm","c2","c2s4"],["adm","c3","c3s2"],["adm","c3","c3s3"],["adm","c3","c3s5"],["adm","c4","c4s4"],["adm","c7","c7s3"],["adm","c8","c8s1"],["adm","c8","c8s6"]]},
    {"id":"p-downs","sid":"adm","name":"唐斯","en":"A. Downs","role":"美國學者","theories":[{"t":"反制法則","n":"上級越想控制部屬，部屬越會設法規避反制。","refs":[["adm","c13","c13s2"]]}],"refs":[["pol","c1","c1s6"],["pol","c6","c6s2"],["pol","c6","c6s5"]]},
    {"id":"p-habermas","sid":"adm","name":"哈伯瑪斯","en":"J. Habermas","role":"德國哲學家","theories":[{"t":"溝通理性與審議民主","n":"民主不只是投票加總偏好，更要讓公民經平等、理性、公開討論形成對公共利益的判斷。","refs":[["adm","c13","c13s3"]]}],"refs":[["adm","c8","c8s3"],["pol","c1","c1s5"],["pol","c4","c4s4"]]},
    {"id":"p-michels","sid":"pol","name":"米契爾斯","en":"R. Michels","role":"菁英理論學者（課文另譯密歇爾斯）","theories":[{"t":"寡頭鐵律","n":"組織越龐大，領導者權力越大，最後由少數人決定多數人的命運。","refs":[["adm","c7","c7s8"]]}],"refs":[["pol","c2","c2s4"],["pol","c4","c4s3"],["pol","c6","c6s3"]]},
    {"id":"p-goodnow","sid":"adm","name":"古德諾","en":"F. J. Goodnow","role":"美國學者，《政治與行政》作者","theories":[{"t":"政治與行政","n":"政治是國家意志的表現，行政是國家意志的執行。","refs":[["adm","c1","c1s3"]]}],"refs":[["adm","c2","c2s1"],["adm","c2","c2s2"],["pol","c5","c5s10"]]},
    {"id":"p-taylor","sid":"adm","name":"泰勒","en":"F. W. Taylor","role":"科學管理代表（不是 R. C. R. Taylor、C. Taylor）","theories":[{"t":"科學管理","n":"管理技術學派代表，傳統時期科學管理運動的一支。","refs":[["adm","c2","c2s1"]]}],"refs":[["adm","c2","c2s2"],["adm","c4","c4s3"],["adm","c4","c4s4"]]},
    {"id":"p-follett","sid":"adm","name":"傅麗德","en":"M. P. Follett","role":"動態管理學派代表","theories":[{"t":"動態管理學派","n":"傳統時期首位系統研究組織中「人」的女性學者，著重行為心理基礎；分期上仍屬傳統時期。","refs":[["adm","c2","c2s4"]]},{"t":"團體的額外價值","n":"團體不只是個人加總，團體生活使人產生影響行動的集體情感。","refs":[["adm","c2","c2s4"]]}],"refs":[["adm","c2","c2s1"],["adm","c3","c3s1"],["adm","c8","c8s5"]]},
    {"id":"p-keynes","sid":"pol","name":"凱因斯","en":"J. M. Keynes","role":"英國經濟學者","theories":[{"t":"政府干預經濟","n":"大恐慌後主張政府積極干預，政府角色由必要之惡轉為積極解決問題，是行政國成因之一。","refs":[["adm","c1","c1s5"]]}],"refs":[["pol","c1","c1s7"],["pol","c3","c3s1"]]},
    {"id":"p-nye","sid":"pol","name":"奈伊","en":"J. S. Nye","role":"美國國際關係學者","theories":[{"t":"互賴理論","n":"與基歐漢（R. O. Keohane）主張國家彼此依賴，可建立國際建制與認知社群。","refs":[["pol","c1","c1s7"]]}],"refs":[["pol","c9","c9s1"],["pol","c9","c9s2"]]},
    {"id":"p-lijphart","sid":"pol","name":"李帕特","en":"A. Lijphart","role":"比較政治學者","theories":[{"t":"多數民主與共識民主","n":"多數模型適合同質性高的社會，共識模型適合異質性高、分歧多的社會。","refs":[["pol","c4","c4s5"]]}],"refs":[["pol","c5","c5s1"],["pol","c6","c6s5"]]},
    {"id":"p-duverger","sid":"pol","name":"杜瓦傑","en":"M. Duverger","role":"法國政治學者","theories":[{"t":"半總統制的定義","n":"總統普選產生；總統有相當實權；另有總理與部長行使行政權，且只要國會不反對就能在職。","refs":[["pol","c5","c5s3"]]}],"refs":[["pol","c6","c6s3"],["pol","c6","c6s5"]]},
    {"id":"p-march","sid":"adm","name":"馬區","en":"J. G. March","role":"美國組織學者","theories":[{"t":"《組織》","n":"與賽蒙合著，亨利典範四「公共行政即管理學」的代表著作。","refs":[["adm","c1","c1s3"]]}],"refs":[["adm","c3","c3s3"],["adm","c8","c8s4"]]},
    {"id":"p-mayo","sid":"adm","name":"梅堯","en":"E. Mayo","role":"哈佛教授，人群關係學派開山學者","theories":[{"t":"霍桑實驗與人群關係","n":"接續霍桑研究，發現人的因素影響生產。人群關係學派開山者是他，不是傅麗德。","refs":[["adm","c3","c3s1"]]}],"refs":[["adm","c2","c2s4"],["adm","c4","c4s4"]]},
    {"id":"p-gaebler","sid":"adm","name":"蓋伯勒","en":"T. Gaebler","role":"《新政府運動》作者之一","theories":[{"t":"《新政府運動》","n":"與歐斯本合著，是企業型政府與新績效預算的來源。","refs":[["adm","c10","c10s1"]]}],"refs":[["adm","c5","c5s3"],["adm","c6","c6s5"]]},
    {"id":"p-ranney","sid":"pol","name":"藍尼","en":"A. Ranney","role":"美國政治學者","theories":[{"t":"政治學的定義","n":"政治學是有系統地研究政治與政府的制度與過程。","refs":[["pol","c1","c1s3"]]}],"refs":[["pol","c2","c2s2"],["pol","c2","c2s9"],["pol","c3","c3s3"],["pol","c4","c4s1"],["pol","c5","c5s6"],["pol","c6","c6s4"]]},
    {"id":"p-waldo","sid":"adm","name":"瓦爾多","en":"D. Waldo","role":"美國行政學者","theories":[{"t":"行政國","n":"1948 年《行政國》提出，指政府職能擴張、行政權獨大、官僚影響政策的狀態。","refs":[["adm","c1","c1s5"]]},{"t":"民主行政","n":"丹哈特政治教育典範的代表。","refs":[["adm","c1","c1s3"]]}],"refs":[["adm","c2","c2s3"],["adm","c5","c5s1"],["adm","c5","c5s2"],["adm","c5","c5s4"]]},
    {"id":"p-kelsen","sid":"jur","name":"凱爾森","en":"H. Kelsen","role":"奧地利法學家，純粹法學代表","theories":[{"t":"集中式違憲審查","n":"其理論推動歐陸的集中式審查。","refs":[["con","c11","c11s3"]]},{"t":"純粹法學","n":"實證法學派，法與道德分離。","refs":[["jur","c1","c1s3"]]}],"refs":[["con","c1","c1s6"],["jur","c2","c2s1"],["jur","c3","c3s3"],["jur","c4","c4s1"]]},
    {"id":"p-smith","sid":"adm","name":"亞當斯密","en":"A. Smith","role":"英國經濟學者（課文也有 T. B. Smith，不同人）","theories":[{"t":"租稅四原則","n":"公平、確定、便利、經濟。","refs":[["adm","c10","c10s3"]]}],"refs":[["adm","c2","c2s2"],["pol","c1","c1s6"],["pol","c1","c1s7"],["pol","c3","c3s1"]]},
    {"id":"p-gulick","sid":"adm","name":"古立克","en":"L. H. Gulick","role":"行政管理學派代表","theories":[{"t":"POSDCORB","n":"計畫、組織、用人、指揮、協調、報告、預算七項管理工作。","refs":[["adm","c1","c1s3"]]}],"refs":[["adm","c2","c2s1"],["adm","c2","c2s3"],["adm","c4","c4s4"],["adm","c7","c7s2"]]},
    {"id":"p-heywood","sid":"pol","name":"海伍德","en":"A. Heywood","role":"英國政治學教科書作者","theories":[{"t":"全球化三立場","n":"支持論、質疑論、改造論（轉型論）。","refs":[["pol","c2","c2s8"]]}],"refs":[["pol","c3","c3s5"],["pol","c6","c6s2"],["pol","c6","c6s4"]]},
    {"id":"p-roosevelt","sid":"con","name":"小羅斯福","en":"F. D. Roosevelt","role":"美國總統","theories":[{"t":"連任四屆","n":"打破兩任慣例；戰後美國以憲法第 22 條增修條文明文化。","refs":[["con","c1","c1s4"]]}],"refs":[["pol","c3","c3s1"],["pol","c5","c5s10"],["pol","c6","c6s6"]]},
    {"id":"p-linz","sid":"pol","name":"林茲","en":"J. J. Linz","role":"比較政治學者","theories":[{"t":"總統制的危險","n":"認為內閣制優於總統制。","refs":[["pol","c4","c4s2"]]},{"t":"威權政體的定義","n":"有限多元、無精密指導意識形態、無廣泛政治動員、領袖在可預測範圍內行使權力。","refs":[["pol","c4","c4s7"]]}],"refs":[["pol","c5","c5s1"],["pol","c5","c5s2"]]},
    {"id":"p-lowi","sid":"adm","name":"羅威","en":"T. J. Lowi","role":"美國政治學者","theories":[{"t":"俘虜性組織","n":"行政機關可能成為利益團體的守護者。","refs":[["adm","c11","c11s2"]]}],"refs":[["adm","c11","c11s5"],["pol","c5","c5s10"],["pol","c6","c6s4"]]},
    {"id":"p-lawrence","sid":"adm","name":"勞倫斯","en":"P. R. Lawrence","role":"權變理論學者，與洛西合著","theories":[{"t":"權變理論三假定","n":"組織沒有最佳方法；任何方法並非同等有效；好的方法取決於實際狀況與環境。","refs":[["adm","c4","c4s3"]]}],"refs":[["adm","c4","c4s4"],["adm","c7","c7s5"],["adm","c8","c8s5"]]},
    {"id":"p-wildavsky","sid":"adm","name":"魏達夫斯基","en":"A. Wildavsky","role":"美國預算與政策學者（課文另譯衛達夫斯基）","theories":[{"t":"預算的政治性","n":"預算是各方協商妥協的結果，多半漸進調整。","refs":[["adm","c10","c10s1"]]},{"t":"《執行》","n":"1973 年與普里斯曼合著，指出共同行動的複雜性使政策執行受阻。","refs":[["adm","c11","c11s3"]]}],"refs":[["adm","c11","c11s4"],["adm","c8","c8s4"]]},
    {"id":"p-lipset","sid":"pol","name":"李普賽","en":"S. M. Lipset","role":"美國政治社會學者","theories":[{"t":"正當性","n":"正當性取決於政治系統是否與社會、道德、宗教價值相符；式微後人民開始不守法。","refs":[["pol","c1","c1s5"]]}],"refs":[["pol","c4","c4s2"],["pol","c6","c6s3"]]},
    {"id":"p-parsons","sid":"pol","name":"帕森斯","en":"T. Parsons","role":"美國社會學者","theories":[{"t":"結構功能論","n":"對結構功能論貢獻最大。","refs":[["pol","c2","c2s5"]]},{"t":"系統的定義","n":"強調部分間相互依賴，也強調整體與外在環境相互依存。","refs":[["adm","c4","c4s1"]]}],"refs":[["adm","c4","c4s4"]]},
    {"id":"p-merton","sid":"adm","name":"墨頓","en":"R. K. Merton","role":"美國社會學者（課文另譯默頓）","theories":[{"t":"官僚反功能與目標錯置","n":"過度遵守規則會把手段當成目的；並借用「訓練有素的無能」。","refs":[["adm","c7","c7s8"]]},{"t":"顯性與隱性功能","n":"分為有意達成的顯性功能與始料未及的隱性功能。","refs":[["pol","c2","c2s5"]]}],"refs":[["adm","c2","c2s5"]]},
    {"id":"p-grotius","sid":"jur","name":"格勞秀斯","en":"H. Grotius","role":"自然法之父","theories":[{"t":"自然法學派","n":"自然法學派代表，也提出主權是不受他人或法律支配的最高權力。","refs":[["jur","c1","c1s3"]]}],"refs":[["jur","c1","c1s4"],["pol","c2","c2s7"]]},
    {"id":"p-fukuyama","sid":"pol","name":"福山","en":"F. Fukuyama","role":"美國政治學者","theories":[{"t":"政治穩定三要素","n":"有效國家、法治、民主問責，缺乏就是失敗國家。","refs":[["pol","c2","c2s8"]]}],"refs":[["pol","c3","c3s3"],["pol","c9","c9s2"]]},
    {"id":"p-thatcher","sid":"adm","name":"柴契爾","en":"M. Thatcher","role":"英國首相","theories":[{"t":"民營化與政府再造","n":"1979 年起推動民營化與效率稽核，1988 年續階計畫設立政署。","refs":[["adm","c6","c6s5"]]}],"refs":[["pol","c2","c2s8"],["pol","c3","c3s4"]]},
    {"id":"p-mill","sid":"pol","name":"彌爾","en":"J. S. Mill","role":"英國思想家，《論自由》作者","theories":[{"t":"傷害原則","n":"自由是社會進步動力，但不得傷害他人。","refs":[["pol","c3","c3s1"]]}],"refs":[["pol","c3","c3s6"],["pol","c4","c4s3"]]},
    {"id":"p-reagan","sid":"adm","name":"雷根","en":"R. Reagan","role":"美國總統","theories":[{"t":"權力回歸各州","n":"府際關係發展中的代表作法。","refs":[["adm","c12","c12s1"]]}],"refs":[["adm","c5","c5s2"],["pol","c3","c3s4"]]},
    {"id":"p-kant","sid":"con","name":"康德","en":"I. Kant","role":"德國哲學家","theories":[{"t":"人本身即是目的","n":"人不能只被當工具，是人性尊嚴與客體公式的基礎。","refs":[["con","c2","c2s3"]]}],"refs":[["jur","c1","c1s3"],["pol","c4","c4s6"]]},
    {"id":"p-sartori","sid":"pol","name":"薩托利","en":"G. Sartori","role":"義大利政治學者","theories":[{"t":"總統制的定義","n":"元首民選且任期固定；總統是行政首長並領導政府；不因國會不信任而去職。","refs":[["pol","c5","c5s2"]]}],"refs":[["pol","c5","c5s3"],["pol","c6","c6s6"]]},
    {"id":"p-key","sid":"adm","name":"凱伊","en":"V. O. Key","role":"美國政治學者（課文另譯奇伊）","theories":[{"t":"民意的定義","n":"政府認為應審慎注意的私人意見。","refs":[["adm","c14","c14s5"]]}],"refs":[["pol","c6","c6s6"],["pol","c7","c7s3"]]},
    {"id":"p-jun","sid":"adm","name":"全鍾燮","en":"J. S. Jun","role":"行政學者","theories":[{"t":"前瞻觀點","n":"行政除回應民眾、適應環境，還要有引導社會變遷的能力。","refs":[["adm","c1","c1s3"]]},{"t":"公共利益八項標準","n":"含公民權利、倫理道德、民主程序、專業知識、非預期結果、共同利益等。","refs":[["adm","c1","c1s4"]]}],"refs":[["adm","c5","c5s4"]]},
    {"id":"p-henry","sid":"adm","name":"亨利","en":"N. Henry","role":"美國行政學者","theories":[{"t":"公共行政典範","n":"用典範描述公共行政發展，由政治行政分立一路到治理。","refs":[["adm","c1","c1s3"]]}],"refs":[["adm","c3","c3s3"],["adm","c4","c4s1"]]},
    {"id":"p-herzberg","sid":"adm","name":"赫茲伯格","en":"F. Herzberg","role":"美國學者，激勵理論代表","theories":[{"t":"激勵保健理論","n":"又稱兩因理論。能防止不滿的是保健因素，另有激勵因素。","refs":[["adm","c3","c3s4"]]}],"refs":[["adm","c3","c3s1"],["adm","c3","c3s5"]]},
    {"id":"p-lorsch","sid":"adm","name":"洛西","en":"J. W. Lorsch","role":"權變理論學者，與勞倫斯合著","theories":[{"t":"權變理論三假定","n":"組織沒有最佳方法，好的方法取決於環境。","refs":[["adm","c4","c4s3"]]}],"refs":[["adm","c4","c4s4"],["adm","c7","c7s5"]]},
    {"id":"p-osborne","sid":"adm","name":"歐斯本","en":"D. Osborne","role":"《新政府運動》作者之一（課文另譯奧斯本）","theories":[{"t":"《新政府運動》","n":"與蓋伯勒合著，提出企業型政府「掌舵而非划槳」。","refs":[["adm","c6","c6s5"]]}],"refs":[["adm","c10","c10s1"],["adm","c5","c5s3"]]},
    {"id":"p-etzioni","sid":"adm","name":"艾桑尼","en":"A. Etzioni","role":"美國社會學者","theories":[{"t":"順從分類","n":"強制權力配疏離（監獄）、功利權力配計利、規範權力配道德；一致時稱調和順從組織。","refs":[["adm","c7","c7s1"]]}],"refs":[["adm","c8","c8s1"],["adm","c8","c8s4"]]},
    {"id":"p-lewin","sid":"adm","name":"李文","en":"K. Lewin","role":"組織發展先驅","theories":[{"t":"力場分析與變革三階段","n":"狀態是驅策力與抑制力的平衡；計畫性變革分解凍、變革（移動）、再結凍。","refs":[["adm","c7","c7s5"]]},{"t":"組織氣候","n":"與李彼特、懷特最早提出。","refs":[["adm","c7","c7s4"]]}],"refs":[["adm","c8","c8s2"]]}
  ],
  rulings: [
    {"id":"r-175","sid":"con","no":"釋字第 175 號","title":"司法院法律提案權案","year":"71","issue":"司法院可否向立法院提法律案？","holding":"基於五權分治、彼此相維，司法院就所掌事項得向立法院提法律案。","note":"提案權主體：行政院第 58 條、考試院第 87 條、監察院釋字 3 號、司法院釋字 175 號、立委。總統不能提。","law":"憲法第 58、87 條","refs":[["con","c10","c10s1"],["con","c11","c11s1"]]},
    {"id":"r-216","sid":"alaw","no":"釋字第 216 號","title":"法官不受函釋拘束案","year":"76","issue":"法官審判是否受行政機關釋示命令拘束？","holding":"法官依法律獨立審判，可引用行政規則，但得依法表示不同見解，不受拘束。","note":"對照 407 號。依課文與解析整理，待核對。","law":"憲法第 80 條","refs":[["alaw","c6","c6s2"],["alaw","c6","c6s3"],["jur","c2","c2s3"]]},
    {"id":"r-224","sid":"con","no":"釋字第 224 號","title":"先繳稅始得復查案","year":"77","issue":"須繳納一定比例稅款或提供擔保才能申請復查，是否違憲？","holding":"該規定限制有財力者才能救濟，侵害人民行政救濟權（訴願、訴訟權），且違反平等，違憲。","note":"題目選項答行政救濟權。依題庫整理，待核對。","law":"憲法第 7、16 條"},
    {"id":"r-261","sid":"con","no":"釋字第 261 號","title":"萬年國會退職案","year":"79","issue":"第一屆中央民意代表應否終止職權？","holding":"民意代表定期改選是貫徹民主憲政的途徑。第一屆中央民代應於 80 年 12 月 31 日前終止職權，辦理次屆選舉。","note":"對照釋字 31 號；原因是定期改選，不是年事已高。","law":"憲法第 28、65 條","refs":[["con","c1","c1s3"],["con","c1","c1s5"]]},
    {"id":"r-329","sid":"jur","no":"釋字第 329 號","title":"條約案","year":"82","issue":"憲法所稱條約的範圍，哪些須送立法院審議？","holding":"指與他國或國際組織締結的國際書面協定，名稱為條約、公約或協定等，內容直接涉及重要事項或人民權利義務且有法律效力者，應送立法院審議。經法律授權或事先同意，或內容與國內法律相同者除外。","note":"不是名稱決定；臺灣與大陸間協議不在本解釋範圍。","law":"憲法第 38、58、63、141 條","refs":[["alaw","c1","c1s3"],["con","c10","c10s2"],["jur","c1","c1s5"],["jur","c2","c2s4"],["jur","c3","c3s5"]]},
    {"id":"r-342","sid":"con","no":"釋字第 342 號","title":"國安三法立法程序案","year":"83","issue":"法律案的立法程序有爭議，釋憲機關可否審查？","holding":"立法程序屬國會內部事項，依議會自律原則應予尊重；除有明顯重大瑕疵、牴觸憲法者外，非釋憲機關審查對象。","note":"不是有瑕疵就違憲，也不是完全不審查，答題關鍵字是「明顯重大」。與 381 號同立場；499 號是少數認定有明顯重大瑕疵的案例。","law":"憲法第 170 條","refs":[["con","c10","c10s1"],["con","c1","c1s2"]]},
    {"id":"r-371","sid":"con","no":"釋字第 371 號","title":"法官聲請釋憲案","year":"84","issue":"法官審理案件認法律違憲時如何處理？","holding":"各級法院法官依合理確信認為法律違憲，得裁定停止訴訟程序，以自己名義聲請解釋，不得逕自拒絕適用。","note":"憲法訴訟法後改為法規範憲法審查。只有憲法法庭得宣告法律違憲。","law":"憲法第 78、80、171 條","refs":[["con","c11","c11s3"],["jur","c5","c5s1"]]},
    {"id":"r-380","sid":"con","no":"釋字第 380 號","title":"大學共同必修科目案","year":"84","issue":"大學法施行細則規定由教育部訂定共同必修科目，是否違憲？","holding":"第 11 條講學自由是對學術自由的制度性保障，就大學教育包含研究自由、教學自由及學習自由。大學法未授權，教育部以施行細則訂定共同必修科目，違反大學自治與法律保留，違憲。","note":"國家可監督大學，但不得干預課程。大學自治的基礎案例。","law":"憲法第 11、162 條","refs":[["con","c2","c2s1"],["con","c5","c5s5"]]},
    {"id":"r-382","sid":"con","no":"釋字第 382 號","title":"大學退學權案","year":"84","issue":"學生受退學處分能否提行政爭訟？","holding":"足以改變學生身分並損及受教機會的退學或類此處分屬行政處分，用盡校內申訴後得提訴願、行政訴訟。私立學校在此類事項上視同行政機關。","note":"其後由 684、784 號放寬。","law":"憲法第 16、21 條","refs":[["alaw","c1","c1s4"],["alaw","c2","c2s3"],["con","c5","c5s5"],["con","c7","c7s1"],["con","c7","c7s3"]]},
    {"id":"r-384","sid":"con","no":"釋字第 384 號","title":"檢肅流氓條例案","year":"84","issue":"檢肅流氓條例的強制到案、秘密證人、感訓處分是否違憲？","holding":"首度引進實質正當法律程序：限制人身自由除有法律依據外，實體與程序內容均須實質正當（含構成要件明確、不得強迫自證己罪、對質詰問、審檢分離、同一行為不重覆處罰、審判公開、救濟）。上開規定違憲。","note":"人身自由的正當法律程序基礎案例。「由檢察官或法官審問處罰」不是本號要件的正確敘述，要看第 8 條的機關區分。","law":"憲法第 8、23 條","refs":[["con","c2","c2s1"],["con","c2","c2s2"],["con","c4","c4s1"],["con","c4","c4s3"],["jur","c4","c4s1"]]},
    {"id":"r-392","sid":"con","no":"釋字第 392 號","title":"羈押權案","year":"84","issue":"檢察官有無羈押權？第 8 條的「法院」範圍？","holding":"第 8 條第 1 項的司法機關採廣義（含檢察機關），第 2 項及後段的法院僅指有審判權的法官。羈押應由法官決定，檢察官羈押權違憲。","note":"逮捕拘禁與審問區分：提審 24 小時。","law":"憲法第 8 條","refs":[["con","c11","c11s1"],["con","c2","c2s2"],["con","c4","c4s1"],["con","c4","c4s3"]]},
    {"id":"r-396","sid":"con","no":"釋字第 396 號","title":"公懲會與懲戒程序案","year":"85","issue":"公務員懲戒僅一級一審，是否違反訴訟權？懲戒程序應如何進行？","holding":"公務員懲戒屬司法權，未設通常上訴救濟不當然違反第 16 條。但懲戒機關應採法院體制，程序須有直接審理、言詞辯論、對審及辯護等正當程序保障。","note":"訴訟權的制度性保障；正當法律程序擴及公務員懲戒的起點。公務員與國家是公法上職務關係。","law":"憲法第 16、77 條","refs":[["alaw","c4","c4s5"],["con","c2","c2s1"],["con","c2","c2s2"]]},
    {"id":"r-401","sid":"alaw","no":"釋字第 401 號","title":"立委言論表決與罷免案","year":"85","issue":"立委因院內言論、表決不當，能否被罷免？","holding":"第 73 條免責是對院外不負責，不及於選舉人依法罷免。原選舉區選舉人仍得因此罷免。","note":"院外不負民刑事責任；立法行為原則不生國賠。範圍參 435 號。","law":"憲法第 73、133 條","refs":[["alaw","c12","c12s3"]]},
    {"id":"r-414","sid":"con","no":"釋字第 414 號","title":"藥物廣告案","year":"85","issue":"藥物廣告事前審查是否違憲？","holding":"藥物廣告是商業言論，受言論自由與財產權保障，但保障較低。為維護國民健康，刊播前應經核准的規定合憲。","note":"高低價值言論的區分出處。注意 744 號化粧品廣告事前審查違憲。","law":"憲法第 11、15、23 條","refs":[["con","c5","c5s1"]]},
    {"id":"r-419","sid":"con","no":"釋字第 419 號","title":"副總統兼任行政院院長案","year":"85","issue":"副總統可否兼任行政院院長？新總統就職時院長總辭的性質？","holding":"兩職性質非顯不相容，但兼任與憲法繼任、代行設計未盡相符，應依解釋意旨適當處理。院長於總統就職時提出總辭屬禮貌性辭職，非憲法義務，其處理屬總統統治行為。","note":"理由書也論及憲政慣例。","law":"憲法第 49、51、55 條","refs":[["con","c1","c1s4"],["con","c9","c9s1"]]},
    {"id":"r-432","sid":"con","no":"釋字第 432 號","title":"會計師不正當行為案","year":"86","issue":"會計師法以「不正當行為」為懲戒事由，是否違反明確性？","holding":"法律可用不確定法律概念或概括條款，只要符合三要件：意義非難以理解、為受規範者所得預見、可經司法審查確認。合憲。","note":"法律明確性三要件的出處，一定要背。","law":"憲法第 15、23 條","refs":[["con","c1","c1s3"],["con","c1","c1s6"]]},
    {"id":"r-436","sid":"con","no":"釋字第 436 號","title":"軍事審判案","year":"86","issue":"軍事審判法不許向普通法院救濟，是否違憲？","holding":"現役軍人可設軍事審判特別程序，但軍事審判機關無專屬審判權，仍屬國家刑罰權，須符合正當法律程序。平時經終審軍事審判宣告有期徒刑以上之刑者，應許以違背法令為由向普通法院救濟，原規定違憲。","note":"非現役軍人不受軍事審判（第 9 條）。","law":"憲法第 8、9、16、23、77、80 條","refs":[["con","c4","c4s3"]]},
    {"id":"r-443","sid":"con","no":"釋字第 443 號","title":"役男出境案","year":"86","issue":"以役男出境處理辦法（命令）限制役男出境，是否合憲？法律保留的密度如何區分？","holding":"限制役男出境屬重大事項，應以法律或法律明確授權的命令規定，該辦法違憲。理由書建立層級化法律保留：憲法保留（第 8 條人身自由）、絕對法律保留（剝奪生命、限制身體自由）、相對法律保留（其他自由權利、給付行政的重大公益事項）、無須法律保留（執行法律的技術性、細節性次要事項）。","reason":"理由書指出，並非一切自由權利都受毫無差別的保障。何種事項應以法律直接規範或得委由命令規定，與規範密度有關，應視規範對象、內容或法益本身及其所受限制的輕重而容許合理差異。也就是：不是所有事項都必須由法律規定，而是依事項的重要性、對人民權利影響的強度，決定規範密度。給付行政的規範密度較限制人民權益者寬鬆，但涉及公共利益重大事項，仍應有法律或法律授權的命令為依據。","note":"不是憲法保留事項，這是常見錯誤選項。給付行政受法律規範的密度較寬鬆，但涉及重大公益仍要有法律或授權。","law":"憲法第 10、23 條","refs":[["alaw","c1","c1s1"],["alaw","c2","c2s1"],["alaw","c6","c6s1"],["con","c1","c1s6"],["con","c2","c2s2"],["con","c4","c4s2"],["con","c7","c7s4"]]},
    {"id":"r-445","sid":"con","no":"釋字第 445 號","title":"集遊法違反明確性案","year":"87","issue":"集會遊行法的事前許可制及不予許可事由是否違憲？","holding":"集會自由與言論自由同屬表現自由。集會遊行的時間、地點、方式限制與內容無關，原則合憲；但以「主張共產主義或分裂國土」為由事前審查言論內容違憲；「有危害國家安全、社會秩序或公共利益之虞」等要件欠缺明確性，亦違憲。","note":"國家應提供適當集會場所、保護集會安全，考點是基本權的保護義務功能。雙軌理論（內容管制與 TPM 管制）常用案例。","law":"憲法第 11、14、23 條","refs":[["con","c2","c2s1"],["con","c2","c2s3"],["con","c5","c5s1"],["con","c5","c5s4"]]},
    {"id":"r-450","sid":"con","no":"釋字第 450 號","title":"大學應設軍訓室案","year":"87","issue":"大學法強制大學設置軍訓室並配置人員，是否違憲？","holding":"大學內部組織屬大學自治範圍，大學法強制設置軍訓室並配置人員，從組織面干預大學自治，違憲。","note":"案名與 380 號（共同必修科目）容易混淆：450 是組織，380 是課程。","law":"憲法第 11、162 條","refs":[["con","c5","c5s5"]]},
    {"id":"r-459","sid":"alaw","no":"釋字第 459 號","title":"兵役體位判定案","year":"87","issue":"兵役體位判定的性質？","holding":"屬行政處分（確認處分），役男不服得依法提起訴願、行政訴訟。","note":"依課文與解析整理，待核對。","law":"憲法第 16 條；訴願法第 1 條","refs":[["alaw","c1","c1s4"],["con","c7","c7s1"]]},
    {"id":"r-461","sid":"con","no":"釋字第 461 號","title":"三院院長備詢與參謀總長案","year":"87","issue":"參謀總長有無備詢義務？三院院長呢？","holding":"立委得向行政院院長及部會首長質詢；參謀總長以有關係政府人員身分應受委員會邀請備詢。基於五院相互尊重與憲政慣例，司法、考試、監察三院院長不受邀請；但預算相關人員應到會說明。","note":"憲政慣例的例子。","law":"憲法第 67 條；增修條文第 3 條","refs":[["con","c10","c10s2"],["con","c12","c12s1"],["con","c1","c1s4"]]},
    {"id":"r-467","sid":"con","no":"釋字第 467 號","title":"精省後省的地位案","year":"87","issue":"精省後，省是否仍為公法人？","holding":"省已不再有憲法規定的自治事項，亦不具備自主組織權，不是地方自治團體性質的公法人；但未劃歸國家或縣市的事項，及法律規定範圍內，仍得為權利義務主體。","note":"地方自治制度受保障，不保障每個層級永久存在。選擇題常考「仍具自治立法權」為錯。","law":"增修條文第 9 條","refs":[["alaw","c3","c3s6"],["con","c13","c13s2"]]},
    {"id":"r-468","sid":"con","no":"釋字第 468 號","title":"總統選舉連署保證金案","year":"87","issue":"無黨籍參選人須連署與繳保證金是否合憲？","holding":"連署制度目的在防止耗費社會資源，未違平等；保證金未逾立法裁量。","note":"施寄青案。對照 340 號（政黨推薦保證金減半違憲）。","law":"憲法第 7 條；增修條文第 2 條","refs":[["con","c7","c7s2"],["con","c8","c8s1"]]},
    {"id":"r-469","sid":"alaw","no":"釋字第 469 號","title":"公務員不作為國賠案","year":"87","issue":"公務員怠於執行職務，人民能否請求國賠？","holding":"法律目的在保障特定人且規定明確、已無裁量空間，公務員仍怠於執行致特定人受害，得請求賠償；僅屬反射利益者不得請求。","note":"保護規範理論；國賠法第 2 條第 2 項後段。","law":"憲法第 24 條；國家賠償法第 2 條","refs":[["alaw","c12","c12s3"],["alaw","c1","c1s4"],["alaw","c2","c2s3"]]},
    {"id":"r-476","sid":"con","no":"釋字第 476 號","title":"毒品死刑案","year":"88","issue":"毒品條例的死刑是否違憲？","holding":"目的正當、手段必要、限制妥當，符合比例原則，合憲。","note":"生命權限制的基礎案例。","law":"憲法第 15、23 條","refs":[["con","c2","c2s4"],["con","c6","c6s1"]]},
    {"id":"r-479","sid":"con","no":"釋字第 479 號","title":"台灣法學會改名案","year":"88","issue":"以作業規定要求團體名稱冠行政區域，是否違憲？","holding":"團體名稱選定屬結社自由範圍，限制須以法律或明確授權命令為之，該規定違反結社自由與法律保留。","note":"人民團體法上的名稱問題，常配 644 號。","law":"憲法第 14、23 條","refs":[["con","c5","c5s4"]]},
    {"id":"r-485","sid":"con","no":"釋字第 485 號","title":"眷村改建案","year":"88","issue":"國軍老舊眷村改建條例給原眷戶優惠，是否違反平等？","holding":"平等是法律地位的實質平等，容許合理差別待遇。社會政策立法應考量財政，依資源有效利用原則分配，不得僅以特定職位或身分作為區別唯一依據。條例給予優惠未違平等，但部分過度優惠的規定應檢討。","note":"促進民生福祉是憲法原則，由前言、第 1 條、基本國策推導。","law":"憲法第 1、7 條；增修條文第 10 條","refs":[["con","c3","c3s1"],["con","c3","c3s2"]]},
    {"id":"r-490","sid":"con","no":"釋字第 490 號","title":"男子服兵役與宗教自由案","year":"88","issue":"兵役法只課男子兵役義務，是否違反平等？人民可否以宗教信仰為由拒服兵役？","holding":"男女生理差異及因此所生的社會功能角色不同，使僅男子服兵役屬合理差別待遇，合憲。內在信仰自由受絕對保障；宗教行為與宗教結社自由只受相對保障。人民不得僅因宗教信仰而免除基本義務。","note":"兵役義務不違反人性尊嚴。常與釋字 573 號的宗教中立、807 號的性別平等對照。","law":"憲法第 7、13、20 條","refs":[["con","c3","c3s2"],["con","c5","c5s3"],["con","c7","c7s4"],["jur","c1","c1s4"]]},
    {"id":"r-498","sid":"con","no":"釋字第 498 號","title":"地方公務員備詢案","year":"88","issue":"地方公務員不到立法院備詢，立法院可否刪減補助款？","holding":"地方自治是憲法保障的制度。上級政府對自治事項僅適法性監督，委辦事項得為適法與適當性監督。地方公務員除法律明定外，得衡酌必要性決定是否到會；立法院不得因此刪減或擱置中央補助款。","note":"垂直分權的基礎案例。","law":"憲法第 67 條；增修條文第 9 條","refs":[["con","c10","c10s2"],["con","c13","c13s2"]]},
    {"id":"r-499","sid":"con","no":"釋字第 499 號","title":"第五次修憲無效案","year":"89","issue":"國民大會第五次修憲（國代延任、以立委選舉結果分配國代席次）是否違憲？修憲有無界限？","holding":"採修憲有界限說：憲法中具有本質重要性而為規範秩序存立基礎者（民主共和國原則、國民主權原則、保障人民權利、權力分立與制衡原則）不得經修憲變更。該次修憲以無記名投票進行，程序有明顯重大瑕疵；國代自行延任違反國民主權與利益迴避原則，條文失其效力。","note":"民意代表任期屆滿應即改選，是與選民約定的首要者。考「何者非修憲界限」時，要對照上列四項原則。","law":"憲法第 1、2、174 條；增修條文","refs":[["con","c10","c10s1"],["con","c14","c14s1"],["con","c1","c1s2"],["con","c1","c1s3"],["con","c1","c1s5"],["con","c1","c1s7"]]},
    {"id":"r-503","sid":"alaw","no":"釋字第 503 號","title":"一行為不二罰案","year":"89","issue":"行為罰與漏稅罰能否併罰？","holding":"一行為不二罰是現代民主法治國家基本原則。處罰性質與種類不同，必須採不同方法才能達成目的時，才可併罰；種類相同，從其一重已足達成目的者，不得再罰。","note":"對照行政罰法第 24 條。依課文與解析整理。","law":"行政罰法第 24 條","refs":[["alaw","c10","c10s2"],["jur","c4","c4s3"]]},
    {"id":"r-509","sid":"con","no":"釋字第 509 號","title":"誹謗罪案","year":"89","issue":"刑法第 310 條誹謗罪是否侵害言論自由？","holding":"言論自由具實現自我、溝通意見、追求真理及監督政治社會活動功能，應予最大限度保障，但為保護名譽可限制，第 310 條合憲。第 3 項不要求行為人自行證明內容確屬真實，依其所提資料有相當理由確信為真實，即不以誹謗罪相繩。","note":"這是合憲性解釋的典型例子。檢察官或自訴人仍負舉證責任。","law":"憲法第 11、23 條；刑法第 310 條","refs":[["con","c1","c1s4"],["con","c5","c5s1"],["con","c7","c7s6"]]},
    {"id":"r-520","sid":"con","no":"釋字第 520 號","title":"核四停建案","year":"90","issue":"行政院停止執行法定預算（核四）是否違憲？","holding":"預算屬措施性法律。維持機關運作及執行法定職務的經費不得停止；非屬國家重要政策變更且合於預算法者，得依合義務裁量裁減或變動。停建涉及重要政策變更，行政院應向立法院提出報告並備質詢；立法院如作反對決議，雙方應協商，或循憲法機制解決。","note":"大法官未就核四該不該蓋表態，重點是權力分立與立法院參與決策。「新任總統不得變更政策」是錯誤敘述。","law":"憲法第 57、63 條；增修條文第 3 條","refs":[["con","c10","c10s2"],["con","c11","c11s3"],["con","c1","c1s1"],["con","c9","c9s1"]]},
    {"id":"r-524","sid":"alaw","no":"釋字第 524 號","title":"健保不給付項目案","year":"90","issue":"健保權利義務可否以行政規則規定？","holding":"健保適用法律保留，授權應具體明確。依法應訂法規命令者，不得以行政規則代替；無轉委任授權者，不得委由所屬機關發布。","note":"給付行政涉重大事項仍受法律保留。","law":"憲法第 23 條；增修條文第 10 條","refs":[["alaw","c2","c2s1"],["alaw","c6","c6s1"],["alaw","c6","c6s2"]]},
    {"id":"r-525","sid":"con","no":"釋字第 525 號","title":"義務預官轉任志願役案","year":"90","issue":"法規變更是否有信賴保護適用？要件？","holding":"法規變更也有信賴保護。不值得保護：法規明顯違反上位規範；當事人以不正當方法或不正確資料促成；純屬主觀期待而無具體信賴行為。須有客觀具體表現的信賴行為。","note":"信賴基礎、信賴表現、信賴值得保護。","law":"憲法第 23 條；行政程序法第 8 條","refs":[["alaw","c2","c2s4"],["con","c1","c1s3"],["con","c1","c1s6"]]},
    {"id":"r-530","sid":"con","no":"釋字第 530 號","title":"司法院定位與審判獨立案","year":"90","issue":"司法院的憲法定位為何？司法自主性包括什麼？","holding":"依制憲本旨，司法院應為最高審判機關，現制僅掌司法行政不符，應檢討修正。審判獨立要求司法自主性，包括法官獨立、司法行政權與規則制定權。","note":"改革方向有最高法院化與憲法法院化。111 年施行憲法訴訟法後，大法官組成憲法法庭。","law":"憲法第 77、80 條","refs":[["con","c11","c11s1"],["con","c11","c11s3"],["jur","c5","c5s1"]]},
    {"id":"r-533","sid":"alaw","no":"釋字第 533 號","title":"健保特約合約案","year":"90","issue":"健保局與特約醫療機構的合約爭議走哪條路？","holding":"屬行政契約，應循行政訴訟解決。","note":"行政契約判斷的常見例。","law":"行政程序法第 135 條；行政訴訟法第 2 條","refs":[["alaw","c8","c8s1"],["jur","c3","c3s3"]]},
    {"id":"r-535","sid":"con","no":"釋字第 535 號","title":"臨檢案","year":"90","issue":"警察勤務條例的臨檢規定，能否作為臨檢依據？要件與程序為何？","holding":"該條例兼有行為法性質，可作臨檢依據，但臨檢影響行動自由、財產權與隱私權，須依法為之。場所限於已發生危害或依客觀合理判斷易生危害者；對人須有相當理由足認已構成或即將發生危害；應出示證件、告知事由，原則現場實施。私人居住空間應與住宅同受保障。","note":"得同行至警局僅限：經同意、無從確定身分、現場盤查不利受檢人或妨礙交通安寧。其後制定警察職權行使法。","law":"憲法第 8、10、22、23 條","refs":[["alaw","c3","c3s7"],["con","c4","c4s2"]]},
    {"id":"r-542","sid":"con","no":"釋字第 542 號","title":"集水區遷村補償金認定案","year":"91","issue":"遷村作業計畫的性質及合憲性？","holding":"遷村計畫目的在保護水資源，有法律授權且未違比例原則，合憲。內部計畫有規制不特定人效果，屬對外生效的命令，可受審查；給付性措施也應遵守平等原則。","note":"課文說屬行政規則性質；法律定性依題目判斷。","law":"憲法第 7、10、23 條","refs":[["alaw","c6","c6s2"],["con","c4","c4s2"]]},
    {"id":"r-553","sid":"alaw","no":"釋字第 553 號","title":"臺北市里長延選案","year":"91","issue":"里長延選的監督及救濟？","holding":"屬地方自治事項，地方不服上級撤銷可循行政救濟。自治事項為適法性監督，委辦事項並及合目的性。本號列出判斷餘地審查時應考量的因素。","note":"不確定法律概念的判斷餘地常引本號。","law":"地方制度法第 75、83 條","refs":[["alaw","c2","c2s3"],["alaw","c3","c3s6"],["con","c13","c13s2"]]},
    {"id":"r-563","sid":"con","no":"釋字第 563 號","title":"碩士考試未通過退學案","year":"92","issue":"大學以學則規定研究生資格考兩次不及格退學，有無違反法律保留及受教權？","holding":"大學自治受憲法制度性保障。大學在不違背法律的範圍內，對學業成績與退學事由有自主訂定學則的權限，法律保留密度可降低，合憲。","note":"退學規定仍應合理、經校內民主程序產生，並給予救濟途徑。與 380、450、626 號一起讀。","law":"憲法第 11、162 條","refs":[["alaw","c1","c1s4"],["con","c5","c5s5"],["con","c7","c7s3"]]},
    {"id":"r-580","sid":"con","no":"釋字第 580 號","title":"三七五減租案","year":"93","issue":"耕地三七五減租條例對收回耕地的限制是否違憲？","holding":"為實現第 143 條第 4 項扶植自耕農，限制出租人收回耕地部分合憲。但第 19 條第 3 項準用第 17 條第 2 項第 3 款，以補償承租人作為收回耕地的附加條件，不當限制財產權，違憲，至遲屆滿兩年失效；一律以三分之一為補償額度也應檢討。","note":"劉沛講義寫「約滿收回需補償承租人，合憲」，與解釋文不符，以解釋文為準。所謂自任耕作不以人力親自實施為限。","law":"憲法第 15、23、143 條"},
    {"id":"r-584","sid":"con","no":"釋字第 584 號","title":"前科者不准計程車執業案","year":"93","issue":"曾犯特定重罪不准辦理計程車執業登記是否違憲？","holding":"屬職業選擇的主觀條件限制，目的在保障乘客安全，符合比例原則與平等，合憲。","note":"主觀條件代表案例，與 749 號（違憲）對照。","law":"憲法第 7、15、23 條","refs":[["con","c2","c2s4"],["con","c6","c6s2"]]},
    {"id":"r-585","sid":"con","no":"釋字第 585 號","title":"真調會條例案","year":"93","issue":"三一九槍擊事件真相調查特別委員會條例是否違憲？立法院調查權的範圍？","holding":"立法院為行使憲法職權享有調查權，得要求提供資料、要求有關人員陳述，並得以法律對違反者為合理強制。但調查事項須與職權有重大關聯；國家機關獨立行使職權受憲法保障者，不在調查範圍，並應尊重行政特權。","note":"立法院調查權與監察院調查權性質有別。考點常連到權力分立，與 325、729 號及 113 年憲判字第 9 號一起看。","law":"憲法第 63、95 條；增修條文第 7 條","refs":[["con","c10","c10s2"],["con","c1","c1s3"]]},
    {"id":"r-588","sid":"con","no":"釋字第 588 號","title":"行政執行拘提管收案","year":"94","issue":"行政執行法的拘提、管收是否符合憲法第 8 條？","holding":"管收是將人民拘束於一定處所，屬剝奪人身自由，應由中立公正的法院審問決定，並踐行必要程序；部分要件違反比例原則，違憲。第 8 條所稱警察採實質意義，由行政執行處執行員執行拘提管收，並不違憲。","note":"形式警察與實質警察的區別。","law":"憲法第 8、23 條","refs":[["alaw","c11","c11s7"],["con","c4","c4s3"]]},
    {"id":"r-596","sid":"con","no":"釋字第 596 號","title":"勞工退休金可否扣押案","year":"94","issue":"勞基法未禁止退休金扣押，與公務人員不同，是否違反平等？","holding":"勞工退休金屬私法債權，受財產權保障。國家對兩者保護方法不同，應整體觀察；未如公務人員規定不得扣押，屬立法形成自由，未違平等。","note":"合理差別待遇。","law":"憲法第 7、153 條"},
    {"id":"r-603","sid":"con","no":"釋字第 603 號","title":"按捺指紋換發身分證案","year":"94","issue":"戶籍法要求按捺指紋始發給身分證，並建檔存取，是否侵害隱私權？","holding":"隱私權雖非憲法明文列舉，仍受第 22 條保障；其中包括個人資料自主控制的資訊隱私權，但非絕對，得依第 23 條以法律明確規定限制。強制按捺指紋並建檔，未明定目的，手段與所欲達成的公益顯失均衡，違憲。","note":"蒐集須有特定重大公益目的、法律明確規定，並有組織與程序上的防護。比例原則衡量性的代表案例。","law":"憲法第 22、23 條","refs":[["alaw","c2","c2s2"],["con","c7","c7s6"]]},
    {"id":"r-613","sid":"con","no":"釋字第 613 號","title":"通傳會組織法案","year":"95","issue":"NCC 委員由政黨比例推薦、審查會審查的組成方式是否違憲？","holding":"行政院為最高行政機關，基於行政一體須對獨立機關的施政負責，應有人事決定權；立法院可予限制，但不得實質剝奪。依立法院政黨比例推薦的規定違反責任政治與權力分立，也影響通訊傳播自由。","note":"獨立機關不當然違憲；考點是行政一體與人事決定權。","law":"憲法第 11、53、56 條","refs":[["alaw","c3","c3s1"],["alaw","c3","c3s7"],["con","c1","c1s3"],["con","c5","c5s5"],["con","c9","c9s1"],["con","c9","c9s2"]]},
    {"id":"r-621","sid":"alaw","no":"釋字第 621 號","title":"義務人死亡後執行罰鍰案","year":"95","issue":"罰鍰處分後義務人死亡，能否對遺產執行？","holding":"罰鍰處分作成而具執行力後，義務人死亡遺有財產者，得依行政執行法第 15 條強制執行，但執行標的限於遺產。處分作成前行為人已死亡者，受處分主體不存在，不得科處罰鍰。","note":"時間點是關鍵：處分前死亡不能罰；處分後死亡可對遺產執行。","law":"行政執行法第 15 條","refs":[["alaw","c11","c11s4"]]},
    {"id":"r-626","sid":"con","no":"釋字第 626 號","title":"警大拒絕色盲招生簡章案","year":"96","issue":"警大碩士班排除色盲是否違憲？","holding":"入學資格屬大學自治，為培養警察人才目的正當，未違平等與比例原則。受教權不包括請求入學許可。","note":"與 563 號合看。","law":"憲法第 7、11、23、159 條","refs":[["alaw","c2","c2s2"],["con","c3","c3s2"],["con","c5","c5s5"],["con","c7","c7s3"]]},
    {"id":"r-632","sid":"con","no":"釋字第 632 號","title":"監委任期屆滿未提名案","year":"96","issue":"總統不提名監委、立法院不行使同意權，是否違憲？","holding":"監察院是憲法機關。總統應適時提名、立法院應適時行使同意權，使憲法機關正常運作；消極不提名或不行使同意權，致監察院無從行使職權，憲法所不許。","note":"立法院仍可對特定人選不同意。","law":"增修條文第 7 條","refs":[["con","c10","c10s2"],["con","c12","c12s2"]]},
    {"id":"r-636","sid":"con","no":"釋字第 636 號","title":"檢肅流氓條例明確性案","year":"97","issue":"流氓認定要件是否明確？","holding":"「欺壓善良」「品行惡劣、遊蕩無賴」牴觸明確性；敲詐勒索、職業性賭場等要件未牴觸。","note":"明確性具體操作。","law":"憲法第 8、23 條","refs":[["con","c1","c1s6"],["jur","c4","c4s1"]]},
    {"id":"r-641","sid":"con","no":"釋字第 641 號","title":"賣一瓶米酒罰二千元案","year":"97","issue":"菸酒稅法超價出售專賣米酒每瓶一律罰 2,000 元是否違憲？","holding":"立法目的正當，但採劃一處罰，於個案顯然過苛時法律未設調整機制，違反比例原則，侵害財產權。","note":"違反比例原則，不是法律保留或平等。行政罰法第 18 條裁量審酌可對照。","law":"憲法第 15、23 條","refs":[["alaw","c10","c10s1"],["alaw","c10","c10s4"],["con","c2","c2s4"],["con","c6","c6s3"]]},
    {"id":"r-649","sid":"con","no":"釋字第 649 號","title":"視障按摩案","year":"97","issue":"按摩業專由視障者從事，是否侵害非視障者工作權？","holding":"禁止非視障者從事按摩業，屬職業選擇的客觀條件限制，應採嚴格審查，違反比例原則與平等原則，違憲。","note":"三階段理論的客觀條件代表案例：執行自由 514、738；主觀條件 584；客觀條件 649。","law":"憲法第 7、15、23 條；增修條文第 10 條","refs":[["con","c2","c2s4"],["con","c3","c3s2"],["con","c6","c6s2"]]},
    {"id":"r-665","sid":"con","no":"釋字第 665 號","title":"法定法官與重罪羈押案","year":"98","issue":"案件合併分配、重罪羈押是否違憲？","holding":"法院可依規則訂補充規範分配案件，合憲（法定法官原則）。重罪羈押不能單以重罪為要件，須有逃亡等相當理由，合憲性限縮。","note":"課文只寫法定法官，講義另寫羈押。兩個考點都要讀。","law":"憲法第 8、16 條；刑事訴訟法第 101 條","refs":[["con","c11","c11s1"],["con","c7","c7s1"]]},
    {"id":"r-690","sid":"con","no":"釋字第 690 號","title":"SARS 必要處置案","year":"100","issue":"強制隔離是否違憲？","holding":"傳染病防治法的留驗、隔離處置屬人身自由限制，但由專業主管機關決定，目的重要，符合法律明確性、比例原則及正當程序，合憲；未設補償等應檢討。","note":"不必由法院審查，與 392、588 號對比。","law":"憲法第 8、23 條","refs":[["alaw","c2","c2s2"],["con","c4","c4s1"],["con","c4","c4s3"]]},
    {"id":"r-696","sid":"con","no":"釋字第 696 號","title":"夫妻所得合併計算案","year":"101","issue":"夫妻非薪資所得強制合併是否違憲？","holding":"使有配偶者稅負高於單身者，違反平等原則。","note":"租稅平等。","law":"憲法第 7、19 條","refs":[["con","c3","c3s2"],["con","c7","c7s4"]]},
    {"id":"r-702","sid":"con","no":"釋字第 702 號","title":"有損師道案","year":"101","issue":"行為不檢有損師道解聘、終身不得聘任是否違憲？","holding":"該要件不違明確性；解聘屬主觀條件限制，合憲。但一律終身不得再任，未設改正機會，違反比例原則。","note":"部分違憲。工作權主觀條件。","law":"憲法第 15、23 條","refs":[["alaw","c2","c2s2"],["con","c6","c6s2"]]},
    {"id":"r-708","sid":"con","no":"釋字第 708 號","title":"外國人收容案","year":"102","issue":"移民署對外國人收容是否須法院決定？","holding":"外國人也受人身自由保障。短暫暫時收容不必由法院決定，但應有司法救濟；受收容人不服應於 24 小時內移送法院；超過暫時收容期間由移民署逕為收容，違反法官保留。","note":"外國人基本權主體。","law":"憲法第 8 條","refs":[["con","c2","c2s1"],["con","c4","c4s3"]]},
    {"id":"r-715","sid":"con","no":"釋字第 715 號","title":"曾受刑之宣告不得報考案","year":"102","issue":"預備軍士官班招生限制是否違憲？","holding":"曾受刑之宣告不分過失與否一律不得報考，對服公職權限制過大，違反比例原則。","note":"必要性審查例。","law":"憲法第 18、23 條","refs":[["alaw","c2","c2s2"],["con","c7","c7s5"]]},
    {"id":"r-718","sid":"con","no":"釋字第 718 號","title":"緊急性偶發性集會案","year":"103","issue":"緊急性、偶發性集會也要事前許可，是否違憲？","holding":"立法者對事前許可或報備有形成自由，但要求偶發性集會申請、緊急性集會須依期限申請，違反比例原則，違憲。","note":"偶發性指無發起人；緊急性指非即刻舉行無法達成目的。","law":"憲法第 14、23 條","refs":[["con","c5","c5s4"]]},
    {"id":"r-721","sid":"con","no":"釋字第 721 號","title":"單一選區兩票制案","year":"103","issue":"修憲採單一選區兩票制與 5% 政黨門檻，是否違憲？","holding":"該等增修條文未違反自由民主憲政秩序，合憲。修憲程序與內容均依 499 號的標準審查。","note":"修憲條文也可受審查的實例。","law":"增修條文第 4 條","refs":[["con","c1","c1s2"],["con","c7","c7s2"]]},
    {"id":"r-728","sid":"con","no":"釋字第 728 號","title":"祭祀公業派下員案","year":"104","issue":"祭祀公業條例依規約認定派下員，是否違反性別平等？","holding":"實質上有性別差別待遇，但目的在維護法秩序安定與私法自治，合憲；仍應與時俱進檢討。","note":"性別平等例外的合憲案。","law":"憲法第 7、15、22 條；增修條文第 10 條","refs":[["con","c3","c3s2"],["con","c5","c5s4"]]},
    {"id":"r-738","sid":"con","no":"釋字第 738 號","title":"電子遊戲場距離案","year":"105","issue":"自治條例規定較中央嚴格的距離限制是否違憲？","holding":"中央立法未排除地方就自治事項作更嚴格規範，營業場所選定受營業自由保障，距離限制屬自治範圍，原則合憲，仍應符合比例原則，不能實質禁止營業。","note":"「中央法破地方法」的例外。職業執行自由寬鬆審查。","law":"憲法第 15、23 條；地方制度法第 18、19、26 條","refs":[["alaw","c3","c3s3"],["con","c13","c13s1"],["con","c6","c6s2"]]},
    {"id":"r-744","sid":"con","no":"釋字第 744 號","title":"化粧品廣告事前審查案","year":"106","issue":"化粧品廣告事前審查是否違憲？","holding":"屬商業言論事前審查，應嚴格審查；無助防止危害，違反言論自由。","note":"對照 414 號藥物廣告。","law":"憲法第 11、23 條","refs":[["alaw","c2","c2s2"],["con","c5","c5s1"]]},
    {"id":"r-747","sid":"alaw","no":"釋字第 747 號","title":"穿越地下徵收地上權案","year":"106","issue":"事業穿越地下，土地所有人能否請求徵收？","holding":"財產權不限所有權被剝奪。逾越社會責任應忍受範圍形成特別犧牲時，所有人得請求需用土地人徵收地上權。","note":"依課文與解析整理，待核對。","law":"憲法第 15 條；土地徵收條例第 57 條","refs":[["alaw","c12","c12s4"],["con","c6","c6s3"]]},
    {"id":"r-748","sid":"con","no":"釋字第 748 號","title":"同性婚姻案","year":"106","issue":"民法未使同性二人成立婚姻關係，是否違憲？","holding":"違反第 22 條婚姻自由與第 7 條平等權。第 7 條所列事由是例示，性傾向也屬之，採較嚴格審查。限期 2 年修法，逾期可依民法登記。","note":"立法不作為的違憲宣告。後續為施行法。","law":"憲法第 7、22 條","refs":[["con","c2","c2s4"],["con","c3","c3s2"],["con","c7","c7s6"]]},
    {"id":"r-749","sid":"con","no":"釋字第 749 號","title":"計程車司機禁業吊照案","year":"106","issue":"計程車駕駛人執業期間犯特定之罪即吊扣執業登記、吊銷駕照並不得再考領，是否合憲？","holding":"不問犯行是否足以顯示對乘客安全具實質風險，一律吊扣、廢止執業登記，逾越必要程度；一律吊銷所有駕照亦過苛，均違反比例原則，侵害工作權。","note":"不是合憲。主觀條件限制的工作權案例，與 584 號（合憲）對照。","law":"憲法第 15、23 條","refs":[["con","c6","c6s2"]]},
    {"id":"r-750","sid":"con","no":"釋字第 750 號","title":"波波牙醫案","year":"106","issue":"外國牙醫學歷須完成臨床實作才能應考是否違憲？","holding":"符合法律保留與比例原則，未違工作權、應考試權與平等。","note":"合憲。","law":"憲法第 7、15、18、23 條","refs":[["con","c3","c3s2"],["con","c7","c7s5"]]},
    {"id":"r-775","sid":"con","no":"釋字第 775 號","title":"累犯加重與更定其刑案","year":"108","issue":"刑法第 47 條累犯加重、第 48 條前段更定其刑是否違憲？","holding":"累犯一律加重最低本刑，於不符罪刑相當的情形下違憲，累犯加重本身則不涉一行為不二罰。第 48 條前段裁判確定後發覺為累犯而更定其刑，違反一事不再理原則。","note":"考第 48 條時答一事不再理，不是信賴保護或不溯及既往。本號不在主要講義，內容取自課文，待核對官方全文。","law":"憲法第 8、23 條；刑法第 47、48 條","refs":[["con","c1","c1s6"],["con","c4","c4s1"]]},
    {"id":"r-784","sid":"con","no":"釋字第 784 號","title":"各級學生訴訟權案","year":"108","issue":"各級學校學生對學校措施能否提起行政爭訟？","holding":"各級學校學生認其權利因學校教育或管理等公權力措施受侵害時，即使非屬退學或類此處分，也得依性質提起行政爭訟，無特別限制必要。","note":"演進順序 382→684→784。顯然輕微、未達權利侵害者不得爭訟；法院對教師與學校的專業判斷應予較高尊重。","law":"憲法第 16 條","refs":[["alaw","c1","c1s4"],["con","c5","c5s5"],["con","c7","c7s1"],["con","c7","c7s3"]]},
    {"id":"r-785","sid":"alaw","no":"釋字第 785 號","title":"外勤消防人員勤休案","year":"108","issue":"公務人員的救濟有無限制？消防人員勤一休一的輪班制及服勤時數規範是否合憲？","holding":"公務人員認權利受違法侵害，均得依措施性質提起相應的行政訴訟，不以侵害嚴重為要件。公務員服務法未就輪班輪休訂定服勤時數上限等框架規範，不符服公職權及健康權的保護要求；未就超勤補償另設合理規定，亦違憲。高雄市消防局勤休方式本身未違法律保留。","note":"特別權力關係瓦解的終點。其後修正公務員服務法第 12 條；考績與管理措施的救濟途徑區別仍要看現行法與題目。","law":"憲法第 16、18 條；公務人員保障法第 77、78、84 條","refs":[["adm","c9","c9s4"],["alaw","c1","c1s4"],["alaw","c4","c4s1"],["alaw","c4","c4s3"]]},
    {"id":"r-787","sid":"alaw","no":"釋字第 787 號","title":"優存利息爭議審判權案","year":"108","issue":"退除役軍人與臺灣銀行的優惠存款利息爭議，由何法院審判？","holding":"退除役軍職人員與臺灣銀行訂立優惠存款契約，所生給付利息的爭議，屬私法關係，由普通法院審判。","note":"二元訴訟制度下依爭議性質定審判權。","law":"憲法第 16 條"},
    {"id":"r-794","sid":"con","no":"釋字第 794 號","title":"限制菸品業者顯名贊助案","year":"109","issue":"禁止菸商以活動促銷或掛名贊助是否違憲？","holding":"屬表意人身分差別待遇，與國民健康目的有合理關聯，合憲；「贊助」不違明確性。「商業」參照相關法律而解，屬體系解釋。","note":"依課文與題庫整理，待核對。","law":"憲法第 7、11、15、23 條","refs":[["con","c5","c5s1"],["jur","c5","c5s2"]]},
    {"id":"r-803","sid":"con","no":"釋字第 803 號","title":"原住民狩獵案","year":"110","issue":"自製獵槍免刑限制與狩獵事前許可是否侵害原住民權利？","holding":"原住民從事狩獵活動屬文化權利，受憲法第 22 條與增修條文第 10 條保障。自製獵槍限制合乎法律明確性與比例原則，但相關管理辦法對自製獵槍安全規範不足。事前許可原則合憲，但非定期性獵捕一律要求 5 日前申請，違反比例原則。","note":"傳統文化包括自用；安全從事合法狩獵涉及生命權、身體權與文化權，但不承認持槍權。","law":"憲法第 22、23 條；增修條文第 10 條第 11、12 項","refs":[["con","c7","c7s3"]]},
    {"id":"r-807","sid":"con","no":"釋字第 807 號","title":"限制女工夜間工作案","year":"110","issue":"勞基法第 49 條第 1 項限制女工夜間工作，是否違反性別平等？","holding":"女性勞工須經工會或勞資會議同意才能夜間工作，男性則無此要求，形成不利差別待遇；國家應以安全措施保護，不能以禁止工作達成目的，手段與目的欠缺實質關聯，違憲失效。","note":"性別分類採中度以上審查。對照 490 號（合憲）。","law":"憲法第 7 條；增修條文第 10 條第 6 項","refs":[["con","c3","c3s2"],["jur","c9","c9s1"]]},
    {"id":"r-111-kp2","sid":"con","no":"111 年憲判字第 2 號","title":"強制公開道歉案","year":"111","issue":"法院判決命加害人公開道歉是否違憲？","holding":"侵害不表意自由與思想自由，違憲，變更釋字 656 號。名譽回復應改用其他手段，例如刊登判決。","note":"考點：基本權衝突與變更 656 號。依課文與題庫整理，待核對。","law":"憲法第 11、22 條；民法第 195 條","refs":[["con","c2","c2s3"],["con","c5","c5s1"]]},
    {"id":"r-111-kp6","sid":"con","no":"111 年憲判字第 6 號","title":"萊劑殘留標準權限爭議案","year":"111","issue":"地方自治條例規定豬肉不得檢出萊克多巴胺，遭中央函告無效或不予核定，是否合憲？","holding":"進口豬肉乙型受體素安全容許量標準屬中央立法事項（憲法第 108、148 條）；函告地方「不得檢出」規定無效及不予核定，未牴觸憲法。","note":"111 年 5 月 13 日公布。依大法官意見書片段整理，主文全文未核對。地方權限行使不得實質架空中央立法權。","law":"憲法第 108、148 條；地方制度法第 30 條","refs":[["con","c13","c13s1"]]},
    {"id":"r-111-kp11","sid":"alaw","no":"111 年憲判字第 11 號","title":"公立大學不續聘教師再申訴案","year":"111","issue":"公立大學就不予維持其不續聘教師措施的再申訴決定，能否提起行政訴訟？不續聘的性質為何？","holding":"最高行政法院 106 年 6 月份第 2 次庭長法官聯席會議決議，關於公立大學就不予維持其不續聘教師措施的再申訴決定不得循序提起行政訴訟的部分，牴觸憲法第 11 條學術自由及第 16 條訴訟權，不再援用。理由指出，大學依聘約不續聘教師，性質是單純基於聘任契約所為的意思表示，與受委託行使公權力審定教師資格的行政處分（釋字 462 號）有別。","note":"111 年 7 月 29 日公布，聲請人是國立臺灣大學。兩個考點都來自本號：不續聘是契約上意思表示；公立大學可就再申訴決定提行政訴訟。主文只處理公立大學。","law":"憲法第 11、16 條；教師法","refs":[["alaw","c1","c1s4"]]},
    {"id":"r-111-kp20","sid":"alaw","no":"111 年憲判字第 20 號","title":"外籍配偶簽證案","year":"111","issue":"外籍配偶居留簽證遭拒，本國配偶能否以自己名義起訴？","holding":"本國配偶沒有為外籍配偶申請簽證的公法上請求權，不能提課予義務訴訟；但得以婚姻自由受限制為由，例外以自己名義提起訴願及撤銷訴訟。","note":"依課文與題庫解析整理，待核對官方全文。","law":"憲法第 16、22 條；行政訴訟法第 4、5 條","refs":[["alaw","c12","c12s2"]]},
    {"id":"r-113-kp6","sid":"con","no":"113 年憲判字第 6 號","title":"消防警察身高案","year":"113","issue":"消防警察身高標準女 160、男 165 公分，是否違憲？","holding":"表面中立，但排除女性比例明顯高於男性，形成間接歧視，使女性應考試服公職權受不利差別待遇，違反平等權。","note":"間接歧視的代表案例。依課文與題庫整理，待核對。","law":"憲法第 7、18 條","refs":[["con","c3","c3s1"],["con","c3","c3s2"],["con","c7","c7s5"]]}
  ]
};
